export type DirectoryCountry = { name: string; officialName: string; nativeName: string; continent: string; region: string; subregion: string; capital: string; area: number; population: number; languages: string; currencies: string; currencyCode: string; borders: string; summary: string };

export const completeCountryDirectory: DirectoryCountry[] = [{"name":"Afghanistan","officialName":"Islamic Republic of Afghanistan","nativeName":"افغانستان","continent":"Asia","region":"Asia","subregion":"Southern Asia","capital":"Kabul","area":652230,"population":0,"languages":"Dari, Pashto, Turkmen","currencies":"Afghan afghani","borders":"IRN, PAK, TKM, UZB, TJK, CHN","summary":"Afghanistan, officially the Islamic Emirate of Afghanistan, is a landlocked country located at the crossroads of Central and South Asia. It is bordered by Pakistan to the east and south, Iran to the west, Turkmenistan to the northwest, Uzbekistan to the north, Tajikistan to the northeast, and China to the northeast and east. Occupying 652,864 square kilometers (252,072 sq mi) of land, the country is predominantly mountainous with plains in the north and the southwest, which are separated by the Hindu Kush mountain range. Kabul is the country's capital and largest city. Afghanistan's population is estimated to be between 35 and 50 million.","currencyCode":"AFN"},{"name":"Angola","officialName":"Republic of Angola","nativeName":"Angola","continent":"Africa","region":"Africa","subregion":"Middle Africa","capital":"Luanda","area":1246700,"population":0,"languages":"Portuguese","currencies":"Angolan kwanza","borders":"COG, COD, ZMB, NAM","summary":"Angola, officially the Republic of Angola, is a country on the western coast of Southern Africa. It is the second-largest Portuguese-speaking (Lusophone) country after Brazil in both total area and population and is the seventh-largest country in Africa. It is bordered by Namibia to the south, the Democratic Republic of the Congo to the north, Zambia to the east, and the Atlantic Ocean to the west. The Angolan province of Cabinda is an exclave on the Atlantic coast, bordering the Republic of the Congo and the Democratic Republic of the Congo. The capital and most populous city is Luanda.","currencyCode":"AOA"},{"name":"Albania","officialName":"Republic of Albania","nativeName":"Shqipëria","continent":"Europe","region":"Europe","subregion":"Southeast Europe","capital":"Tirana","area":28748,"population":0,"languages":"Albanian","currencies":"Albanian lek","borders":"MNE, GRC, MKD, UNK","summary":"Albania, officially the Republic of Albania, is a country in Southeast Europe. It is located in the Balkans, on the Adriatic and Ionian Seas within the Mediterranean Sea, and shares land borders with Montenegro to the northwest, Kosovo to the northeast, North Macedonia to the east and Greece to the south. With an area of 28,748 km2 (11,100 sq mi), it has a varied range of climatic, geological, hydrological and morphological conditions. Albania's landscapes range from rugged snow-capped mountains in the Albanian Alps and the Korab, Skanderbeg, Pindus and Ceraunian Mountains, to fertile lowland plains extending from the Adriatic and Ionian seacoasts. Tirana is the capital and largest city in the country, followed by Durrës, Vlorë, and Shkodër.","currencyCode":"ALL"},{"name":"Andorra","officialName":"Principality of Andorra","nativeName":"Andorra","continent":"Europe","region":"Europe","subregion":"Southern Europe","capital":"Andorra la Vella","area":468,"population":0,"languages":"Catalan","currencies":"Euro","borders":"FRA, ESP","summary":"Andorra, officially the Principality of Andorra, is a landlocked country on the Iberian Peninsula, in the eastern Pyrenees in southwestern Europe, bordered by France to the north and Spain to the south. Believed to have been created by Charlemagne, Andorra was ruled by the count of Urgell until 988, when it was transferred to the Diocese of Urgell. Andorra was formed as a polity by a charter in 1278, being a lordship within the Principality of Catalonia until 1715. It is currently headed by two co-princes: the Bishop of Urgell in Catalonia, Spain, and the president of France. Its capital and largest city is Andorra la Vella.","currencyCode":"EUR"},{"name":"United Arab Emirates","officialName":"United Arab Emirates","nativeName":"الإمارات","continent":"Asia","region":"Asia","subregion":"Western Asia","capital":"Abu Dhabi","area":83600,"population":0,"languages":"Arabic","currencies":"United Arab Emirates dirham","borders":"OMN, SAU","summary":"The United Arab Emirates (UAE), also known simply as the Emirates, is a country in West Asia, situated at the eastern end of the Arabian Peninsula. It is a federal semi-constitutional monarchy made up of seven emirates, with Abu Dhabi serving as its national capital. The UAE borders Oman to the east and northeast, and Saudi Arabia to the south and southwest. It shares maritime borders with Saudi Arabia, Qatar, and Iran in the Persian Gulf, and with Oman in the Gulf of Oman. In 2024, the UAE had an estimated population of over 11 million. Dubai is the country's largest city. Islam is the state religion. Arabic is the official language while English remains the most spoken language and the language of business.","currencyCode":"AED"},{"name":"Argentina","officialName":"Argentine Republic","nativeName":"Argentina","continent":"South America","region":"Americas","subregion":"South America","capital":"Buenos Aires","area":2780400,"population":0,"languages":"Guaraní, Spanish","currencies":"Argentine peso","borders":"BOL, BRA, CHL, PRY, URY","summary":"Argentina, officially the Argentine Republic, is a country in the far south of South America. It covers an area of 2,780,085 km2 (1,073,397 mi2), making it the second-largest country in South America after Brazil, the fourth-largest country in the Americas, and the eighth-largest country in the world. Argentina shares the bulk of the Southern Cone with Chile to the west, and is also bordered by Bolivia and Paraguay to the north, Brazil to the northeast, Uruguay and the South Atlantic Ocean to the east, and the Drake Passage to the south. Argentina is a federal state divided into twenty-three provinces, and one autonomous city, which is the federal capital and largest city of the nation, Buenos Aires. The provinces and the capital have their own constitutions, but exist under a federal system. Argentina claims sovereignty over the Falkland Islands, South Georgia and the South Sandwich Islands, the Southern Patagonian Ice Field, and a part of Antarctica.","currencyCode":"ARS"},{"name":"Armenia","officialName":"Republic of Armenia","nativeName":"Հայաստան","continent":"Asia","region":"Asia","subregion":"Western Asia","capital":"Yerevan","area":29743,"population":0,"languages":"Armenian","currencies":"Armenian dram","borders":"AZE, GEO, IRN, TUR","summary":"Armenia, officially the Republic of Armenia, is a landlocked country in the Armenian highlands of West Asia. It is a part of the Caucasus region and is bordered by Turkey to the west, Georgia to the north, Azerbaijan to the east, and Iran and the Azerbaijani exclave of Nakhchivan to the south. Yerevan is the capital, largest city and financial center.","currencyCode":"AMD"},{"name":"Antigua and Barbuda","officialName":"Antigua and Barbuda","nativeName":"Antigua and Barbuda","continent":"North America","region":"Americas","subregion":"Caribbean","capital":"Saint John's","area":442,"population":0,"languages":"English","currencies":"Eastern Caribbean dollar","borders":"","summary":"Antigua and Barbuda is an archipelagic country in the Caribbean composed of Antigua, Barbuda, and dozens of other small islands. Antigua and Barbuda has a total area of 440 km2, making it one of the smallest countries in the Caribbean. The country is mostly flat, with the highest points on Antigua being in the Shekerley Mountains and on Barbuda the Highlands. The country has a tropical savanna climate, with pockets of tropical monsoon in Antigua's southwest. Its most populated city is St. John's, followed by All Saints and Bolans. The sole settlement in Barbuda is Codrington. Most of the country resides in the Central Plain that stretches from St. John's to English Harbour.","currencyCode":"XCD"},{"name":"Australia","officialName":"Commonwealth of Australia","nativeName":"Australia","continent":"Oceania","region":"Oceania","subregion":"Australia and New Zealand","capital":"Canberra","area":7692024,"population":0,"languages":"English","currencies":"Australian dollar","borders":"","summary":"Australia, officially the Commonwealth of Australia, is a country comprising the mainland of the Australian continent, the island of Tasmania and numerous smaller islands. It has a land area of 7,688,287 km2 (2,968,464 sq mi), making it the sixth-largest country in the world, and is the world's flattest and driest inhabited continent. It is a megadiverse country, and its size gives it a wide variety of landscapes and climates, including deserts in the interior and tropical rainforests along the coast.","currencyCode":"AUD"},{"name":"Austria","officialName":"Republic of Austria","nativeName":"Österreich","continent":"Europe","region":"Europe","subregion":"Central Europe","capital":"Vienna","area":83871,"population":0,"languages":"Austro-Bavarian German","currencies":"Euro","borders":"CZE, DEU, HUN, ITA, LIE, SVK, SVN, CHE","summary":"Austria, formally the Republic of Austria, is a landlocked country in Central Europe, lying in the Eastern Alps. It is a federation of nine states, of which the capital Vienna is the most populous city and state. Austria is bordered by Germany to the northwest, the Czech Republic to the north, Slovakia to the northeast, Hungary to the east, Slovenia and Italy to the south, and Switzerland and Liechtenstein to the west. The country occupies an area of 83,879 km2 (32,386 sq mi) and has a population of about 9.2 million.","currencyCode":"EUR"},{"name":"Azerbaijan","officialName":"Republic of Azerbaijan","nativeName":"Azərbaycan","continent":"Asia","region":"Asia","subregion":"Western Asia","capital":"Baku","area":86600,"population":0,"languages":"Azerbaijani, Russian","currencies":"Azerbaijani manat","borders":"ARM, GEO, IRN, RUS, TUR","summary":"Azerbaijan, officially the Republic of Azerbaijan, is a landlocked country at the boundary of Western Asia and Eastern Europe. It is a part of the South Caucasus region and is bounded by the Caspian Sea to the east, Russia's republic of Dagestan to the north, Georgia to the northwest, Turkey and Armenia to the west, and Iran to the south. Baku is the capital and largest city.","currencyCode":"AZN"},{"name":"Burundi","officialName":"Republic of Burundi","nativeName":"Burundi","continent":"Africa","region":"Africa","subregion":"Eastern Africa","capital":"Gitega","area":27834,"population":0,"languages":"French, Kirundi","currencies":"Burundian franc","borders":"COD, RWA, TZA","summary":"Burundi, officially the Republic of Burundi, is a landlocked country in East Africa. It is located in the Great Rift Valley at the junction between the African Great Lakes region and southeastern Africa, with a population of over 14 million people. It is bordered by Rwanda to the north, Tanzania to the east and southeast, and the Democratic Republic of the Congo to the west; Lake Tanganyika lies along its southwestern border. The political capital city is Gitega and the economic capital and largest city is Bujumbura.","currencyCode":"BIF"},{"name":"Belgium","officialName":"Kingdom of Belgium","nativeName":"Belgien","continent":"Europe","region":"Europe","subregion":"Western Europe","capital":"Brussels","area":30528,"population":0,"languages":"German, French, Dutch","currencies":"Euro","borders":"FRA, DEU, LUX, NLD","summary":"Belgium, officially the Kingdom of Belgium, is a country in Northwestern Europe. Situated in a coastal lowland region known as the Low Countries, it is bordered by the Netherlands to the north, Germany to the east, Luxembourg to the southeast, France to the south, and the North Sea to the west. Belgium covers an area of 30,689 km2 (11,849 sq mi) and has a population of more than 11.8 million; its population density of 383/km2 (990/sq mi) ranks 22nd in the world and sixth in Europe. The capital and largest metropolitan region is Brussels; other major cities are Antwerp, Ghent, Charleroi, Liège, Bruges, Namur, and Leuven.","currencyCode":"EUR"},{"name":"Benin","officialName":"Republic of Benin","nativeName":"Bénin","continent":"Africa","region":"Africa","subregion":"Western Africa","capital":"Porto-Novo","area":112622,"population":0,"languages":"French","currencies":"West African CFA franc","borders":"BFA, NER, NGA, TGO","summary":"Benin, officially the Republic of Benin, formerly known as Dahomey, is a country in West Africa. It is bordered by Togo to the west, Nigeria to the east, Burkina Faso to the northwest, and Niger to the northeast. The majority of its population lives on the southern coastline of the Bight of Benin, part of the Gulf of Guinea in the northernmost tropical portion of the Atlantic Ocean. The capital is Porto-Novo, and the seat of government is in Cotonou, the most populous city and economic capital. Benin covers an area of 112,622 km2 (43,484 sq mi), and its population in 2026 was estimated to be approximately 15 million. It is a tropical country with an economy heavily dependent on agriculture and the exports of palm oil and cotton.","currencyCode":"XOF"},{"name":"Burkina Faso","officialName":"Burkina Faso","nativeName":"Burkina Faso","continent":"Africa","region":"Africa","subregion":"Western Africa","capital":"Ouagadougou","area":272967,"population":0,"languages":"French","currencies":"West African CFA franc","borders":"BEN, CIV, GHA, MLI, NER, TGO","summary":"Burkina Faso is a landlocked country in West Africa. It is bordered by Mali to the northwest, Niger to the northeast, Benin to the southeast, Togo and Ghana to the south, and Ivory Coast to the southwest. It covers an area of 274,223 km2 (105,878 sq mi). In 2024, the country had an estimated population of approximately 23,286,000. Its citizens are known as Burkinabes, and its capital and largest city is Ouagadougou.","currencyCode":"XOF"},{"name":"Bangladesh","officialName":"People's Republic of Bangladesh","nativeName":"বাংলাদেশ","continent":"Asia","region":"Asia","subregion":"Southern Asia","capital":"Dhaka","area":147570,"population":0,"languages":"Bengali","currencies":"Bangladeshi taka","borders":"MMR, IND","summary":"Bangladesh, officially the People's Republic of Bangladesh, is a country in South Asia. It is the eighth-most populous country in the world with a population of almost 177.8 million people within an area of 148,461 square kilometres (57,321 sq mi). Bangladesh shares land borders with India to the north, west, and east, and Myanmar to the southeast. It has a coastline along the Bay of Bengal to its south and is separated from Bhutan and Nepal by the Siliguri Corridor, and from China by the Indian states of West Bengal and Sikkim to its north. Dhaka, the capital and largest city, is the nation's political, financial, and cultural centre. Chittagong is the second-largest city and the busiest port of the country.","currencyCode":"BDT"},{"name":"Bulgaria","officialName":"Republic of Bulgaria","nativeName":"България","continent":"Europe","region":"Europe","subregion":"Southeast Europe","capital":"Sofia","area":110879,"population":0,"languages":"Bulgarian","currencies":"Euro","borders":"GRC, MKD, ROU, SRB, TUR","summary":"Bulgaria, officially the Republic of Bulgaria, is a country in Southeastern Europe. It is situated on the eastern portion of the Balkans directly south of the Danube river and west of the Black Sea. Bulgaria is bordered by Greece and Turkey to the south, Serbia and North Macedonia to the west, and Romania across the Danube river to the north. It covers a territory of 110,994 square kilometres (42,855 sq mi), making it the tenth largest within the European Union and the sixteenth-largest country in Europe by area. Sofia is the nation's capital and largest city; other major cities include Plovdiv, Varna, and Burgas.","currencyCode":"EUR"},{"name":"Bahrain","officialName":"Kingdom of Bahrain","nativeName":"البحرين","continent":"Asia","region":"Asia","subregion":"Western Asia","capital":"Manama","area":765,"population":0,"languages":"Arabic","currencies":"Bahraini dinar","borders":"","summary":"","currencyCode":"BHD"},{"name":"Bahamas","officialName":"Commonwealth of the Bahamas","nativeName":"Bahamas","continent":"North America","region":"Americas","subregion":"Caribbean","capital":"Nassau","area":13943,"population":0,"languages":"English","currencies":"Bahamian dollar, United States dollar","borders":"","summary":"The Bahamas, officially the Commonwealth of The Bahamas, is an archipelagic country in the Caribbean located within the Lucayan Archipelago in the Atlantic Ocean. The country comprises 700 islands, and more than 2,500 cays in the Atlantic Ocean, located north of Cuba and north-west of the island of Hispaniola and the Turks and Caicos Islands, southeast of the US state of Florida and east of the Florida Keys. The capital and largest city is Nassau on the island of New Providence. The Royal Bahamas Defence Force describes the Bahamas' territory as encompassing 470,000 km2 (180,000 sq mi) of ocean space.","currencyCode":"BSD"},{"name":"Bosnia and Herzegovina","officialName":"Bosnia and Herzegovina","nativeName":"Bosna i Hercegovina","continent":"Europe","region":"Europe","subregion":"Southeast Europe","capital":"Sarajevo","area":51209,"population":0,"languages":"Bosnian, Croatian, Serbian","currencies":"Bosnia and Herzegovina convertible mark","borders":"HRV, MNE, SRB","summary":"","currencyCode":"BAM"},{"name":"Belarus","officialName":"Republic of Belarus","nativeName":"Белару́сь","continent":"Europe","region":"Europe","subregion":"Eastern Europe","capital":"Minsk","area":207600,"population":0,"languages":"Belarusian, Russian","currencies":"Belarusian ruble","borders":"LVA, LTU, POL, RUS, UKR","summary":"","currencyCode":"BYN"},{"name":"Belize","officialName":"Belize","nativeName":"Belize","continent":"North America","region":"Americas","subregion":"Central America","capital":"Belmopan","area":22966,"population":0,"languages":"Belizean Creole, English, Spanish","currencies":"Belize dollar","borders":"GTM, MEX","summary":"","currencyCode":"BZD"},{"name":"Bolivia","officialName":"Plurinational State of Bolivia","nativeName":"Wuliwya","continent":"South America","region":"Americas","subregion":"South America","capital":"Sucre","area":1098581,"population":0,"languages":"Aymara, Guaraní, Quechua, Spanish","currencies":"Bolivian boliviano","borders":"ARG, BRA, CHL, PRY, PER","summary":"","currencyCode":"BOB"},{"name":"Brazil","officialName":"Federative Republic of Brazil","nativeName":"Brasil","continent":"South America","region":"Americas","subregion":"South America","capital":"Brasília","area":8515767,"population":0,"languages":"Portuguese","currencies":"Brazilian real","borders":"ARG, BOL, COL, GUF, GUY, PRY, PER, SUR, URY, VEN","summary":"Brazil, officially the Federative Republic of Brazil, is the largest country in South America. It is also the world's fifth-largest country by area and the seventh-largest by population, with over 214 million people. Brazil is a federation composed of 26 states and a Federal District, which hosts the capital, Brasília. Its most populous city is São Paulo, followed by Rio de Janeiro. Brazil has the largest Lusophone population in the world and is the only Portuguese-speaking country in the Americas, where it is the official language.","currencyCode":"BRL"},{"name":"Barbados","officialName":"Barbados","nativeName":"Barbados","continent":"North America","region":"Americas","subregion":"Caribbean","capital":"Bridgetown","area":430,"population":0,"languages":"English","currencies":"Barbadian dollar","borders":"","summary":"Barbados is an island nation in the Caribbean located in the Atlantic Ocean. It is part of the Lesser Antilles of the West Indies and is the southern and easternmost island of the Caribbean region. It lies on the boundary of the South American and Caribbean plates. Its capital and largest city is Bridgetown.","currencyCode":"BBD"},{"name":"Brunei","officialName":"Nation of Brunei, Abode of Peace","nativeName":"Negara Brunei Darussalam","continent":"Asia","region":"Asia","subregion":"South-Eastern Asia","capital":"Bandar Seri Begawan","area":5765,"population":0,"languages":"Malay","currencies":"Brunei dollar, Singapore dollar","borders":"MYS","summary":"","currencyCode":"BND"},{"name":"Bhutan","officialName":"Kingdom of Bhutan","nativeName":"འབྲུག་ཡུལ་","continent":"Asia","region":"Asia","subregion":"Southern Asia","capital":"Thimphu","area":38394,"population":0,"languages":"Dzongkha","currencies":"Bhutanese ngultrum, Indian rupee","borders":"CHN, IND","summary":"","currencyCode":"BTN"},{"name":"Botswana","officialName":"Republic of Botswana","nativeName":"Botswana","continent":"Africa","region":"Africa","subregion":"Southern Africa","capital":"Gaborone","area":582000,"population":0,"languages":"English, Tswana","currencies":"Botswana pula","borders":"NAM, ZAF, ZMB, ZWE","summary":"","currencyCode":"BWP"},{"name":"Central African Republic","officialName":"Central African Republic","nativeName":"République centrafricaine","continent":"Africa","region":"Africa","subregion":"Middle Africa","capital":"Bangui","area":622984,"population":0,"languages":"French, Sango","currencies":"Central African CFA franc","borders":"CMR, TCD, COD, COG, SSD, SDN","summary":"The Central African Republic (CAR) is a landlocked country in Central Africa. It is bordered by Chad to the north, Sudan to the northeast, South Sudan to the east, the Democratic Republic of the Congo to the south, the Republic of the Congo to the southwest, and Cameroon to the west. The CAR covers a land area of about 620,000 square kilometres (240,000 sq mi). As of 2024, it has a population of 5,357,744, consisting of about 80 ethnic groups. Having been a French colony under the name Ubangi-Shari, Sango is its national language and was also its co-official language alongside French. Its capital and largest city is Bangui, which sits on the country's southern border with the Democratic Republic of the Congo.","currencyCode":"XAF"},{"name":"Canada","officialName":"Canada","nativeName":"Canada","continent":"North America","region":"Americas","subregion":"North America","capital":"Ottawa","area":9984670,"population":0,"languages":"English, French","currencies":"Canadian dollar","borders":"USA","summary":"Canada is a country in North America. Its ten provinces and three territories extend from the Atlantic Ocean to the Pacific Ocean and northward into the Arctic Ocean, making it the second-largest country by total area, with the longest coastline of any country. Its border with the United States is the longest international land border. The country is characterized by a wide range of both meteorologic and geological regions. With a population of over 41 million, it has widely varying population densities, with the majority residing in its urban areas and large areas being sparsely populated. Its capital is Ottawa and its three largest metropolitan areas are Toronto, Montreal, and Vancouver.","currencyCode":"CAD"},{"name":"Switzerland","officialName":"Swiss Confederation","nativeName":"Suisse","continent":"Europe","region":"Europe","subregion":"Western Europe","capital":"Bern","area":41284,"population":0,"languages":"French, Swiss German, Italian, Romansh","currencies":"Swiss franc","borders":"AUT, FRA, ITA, LIE, DEU","summary":"Switzerland, officially the Swiss Confederation, is a landlocked country located at the intersection of Central, Western, and Southern Europe. It is bordered by Germany to the north, France to the west, Austria and Liechtenstein to the east, and Italy to the south. Switzerland is geographically divided among the Swiss Alps, the Swiss Plateau, and the Jura Mountains; the Alps cover most of the country's territory, whereas the majority of its 9 million people are concentrated on the plateau, which hosts many of the largest cities and economic centres, including Zurich, Geneva, Basel, Bern, Lausanne, Winterthur, and Lucerne.","currencyCode":"CHF"},{"name":"Chile","officialName":"Republic of Chile","nativeName":"Chile","continent":"South America","region":"Americas","subregion":"South America","capital":"Santiago","area":756102,"population":0,"languages":"Spanish","currencies":"Chilean peso","borders":"ARG, BOL, PER","summary":"Chile, officially the Republic of Chile, is a country in the Southern Cone of southwestern South America. It is the southernmost country in the world and the closest to Antarctica, extending along a narrow strip of land between the Andes Mountains and the Pacific Ocean. According to the 2024 census, Chile had an enumerated population of 18.5 million. The country covers a territorial area of 756,102 square kilometers (291,933 sq mi), sharing borders with Peru to the north, Bolivia to the northeast, Argentina to the east, and the Drake Passage to the south. It also administers several Pacific islands, including Juan Fernández, Isla Salas y Gómez, Desventuradas, and Easter Island, and claims about 1,250,000 square kilometers (480,000 sq mi) of Antarctica as the Chilean Antarctic Territory. The capital and largest city is Santiago, and the official and national language is Spanish.","currencyCode":"CLP"},{"name":"China","officialName":"People's Republic of China","nativeName":"中国","continent":"Asia","region":"Asia","subregion":"Eastern Asia","capital":"Beijing","area":9706961,"population":0,"languages":"Chinese","currencies":"Chinese yuan","borders":"AFG, BTN, MMR, HKG, IND, KAZ, NPL, PRK, KGZ, LAO, MAC, MNG, PAK, RUS, TJK, VNM","summary":"China, officially the People's Republic of China (PRC), is a country in East Asia. It is divided into 33 province-level divisions, including two special administrative regions. Beijing is the capital, while Shanghai is the most populous city by urban area. Its geography features the Central Plain, major rivers such as the Yangtze and Yellow River, deserts, subtropical and temperate forests, plateaus, and mountain ranges such as the Himalayas. It is the world's second-most populous country after India, with a population exceeding 1.4 billion. Covering 9.6 million square kilometers (3,700,000 sq mi), it is the third largest country by area.","currencyCode":"CNY"},{"name":"Ivory Coast","officialName":"Republic of Côte d'Ivoire","nativeName":"Côte d'Ivoire","continent":"Africa","region":"Africa","subregion":"Western Africa","capital":"Yamoussoukro","area":322463,"population":0,"languages":"French","currencies":"West African CFA franc","borders":"BFA, GHA, GIN, LBR, MLI","summary":"Ivory Coast, also known as Côte d'Ivoire and officially as the Republic of Côte d'Ivoire, is a country on the southern coast of West Africa. Its capital city of Yamoussoukro is located in the centre of the country, while its largest city and economic centre is the port city of Abidjan. It borders Guinea to the northwest, Liberia to the west, Mali to the north, Burkina Faso to the northeast, Ghana to the east, and the Atlantic Ocean's Gulf of Guinea to the south. With 31.5 million inhabitants in 2024, Ivory Coast is the third-most populous country in West Africa after Nigeria and Ghana. Its official language is French, and indigenous languages are also widely used, including Bété, Baoulé, Dyula, Dan, Anyin, and Cebaara Senufo. In total, there are around 78 languages spoken in Ivory Coast. The country has a religiously diverse population, including numerous followers of Islam, Christianity and traditional faiths often entailing animism.","currencyCode":"XOF"},{"name":"Cameroon","officialName":"Republic of Cameroon","nativeName":"Cameroon","continent":"Africa","region":"Africa","subregion":"Middle Africa","capital":"Yaoundé","area":475442,"population":0,"languages":"English, French","currencies":"Central African CFA franc","borders":"CAF, TCD, COG, GNQ, GAB, NGA","summary":"Cameroon, officially the Republic of Cameroon, is a country in Central Africa. It shares boundaries with Nigeria to the west and north, Chad to the northeast, the Central African Republic to the east, and Equatorial Guinea, Gabon, and the Republic of the Congo to the south. Its coastline lies on the Bight of Biafra, part of the Gulf of Guinea, and the Atlantic Ocean. Due to its strategic position at the crossroads between West Africa and Central Africa, it has been categorized as being in both geostrategic locations. Cameroon's population of nearly 31 million people speak 250 native languages, in addition to the national tongues of English and French. The capital city of the country is Yaoundé.","currencyCode":"XAF"},{"name":"DR Congo","officialName":"Democratic Republic of the Congo","nativeName":"RD Congo","continent":"Africa","region":"Africa","subregion":"Middle Africa","capital":"Kinshasa","area":2344858,"population":0,"languages":"French, Kikongo, Lingala, Tshiluba, Swahili","currencies":"Congolese franc","borders":"AGO, BDI, CAF, COG, RWA, SSD, TZA, UGA, ZMB","summary":"","currencyCode":"CDF"},{"name":"Congo","officialName":"Republic of the Congo","nativeName":"République du Congo","continent":"Africa","region":"Africa","subregion":"Middle Africa","capital":"Brazzaville","area":342000,"population":0,"languages":"French, Kikongo, Lingala","currencies":"Central African CFA franc","borders":"AGO, CMR, CAF, COD, GAB","summary":"","currencyCode":"XAF"},{"name":"Colombia","officialName":"Republic of Colombia","nativeName":"Colombia","continent":"South America","region":"Americas","subregion":"South America","capital":"Bogotá","area":1141748,"population":0,"languages":"Spanish","currencies":"Colombian peso","borders":"BRA, ECU, PAN, PER, VEN","summary":"Colombia, officially the Republic of Colombia, is a country located in South America, with insular regions in North America. Colombia's mainland is bordered by the Caribbean Sea to the north, Venezuela to the east, Brazil to the southeast, Peru and Ecuador to the south and southwest, the Pacific Ocean to the west, and Panama to the northwest. Colombia is divided into 32 departments. The Capital District of Bogotá is the country's largest city hosting the main financial and cultural hub. Other urban areas include Medellín, Cali, Barranquilla, Cartagena, Bucaramanga, Pereira, Santa Marta, Cúcuta, Ibagué, Villavicencio and Manizales. It covers an area of 1,141,748 square kilometers and has a population of around 52 million. Its rich cultural heritage—including language, religion, cuisine, and art—reflects its history as a colony, fusing cultural elements brought by immigration from Europe and the Middle East, with those brought by the African diaspora, as well as with those of Indigenous civilizations that predate colonization. Spanish is the official language, although Creole, English and 64 other languages are recognized regionally.","currencyCode":"COP"},{"name":"Comoros","officialName":"Union of the Comoros","nativeName":"جزر القمر","continent":"Africa","region":"Africa","subregion":"Eastern Africa","capital":"Moroni","area":1862,"population":0,"languages":"Arabic, French, Comorian","currencies":"Comorian franc","borders":"","summary":"The Comoros, officially the Union of the Comoros, is an archipelagic country made up of three islands in Southeast Africa, located at the northern end of the Mozambique Channel in the Indian Ocean. Its capital and largest city is Moroni. The predominant religion of the population—and the official state religion—is Islam. Comoros proclaimed its independence from France on 6 July 1975. The country has three official languages: Comorian, French and Arabic. The Comoros is the only country of the Arab League which is entirely in the Southern Hemisphere. It is also a member state of the African Union, the Organisation internationale de la Francophonie, the Organisation of Islamic Cooperation, and the Indian Ocean Commission.","currencyCode":"KMF"},{"name":"Cape Verde","officialName":"Republic of Cabo Verde","nativeName":"Cabo Verde","continent":"Africa","region":"Africa","subregion":"Western Africa","capital":"Praia","area":4033,"population":0,"languages":"Portuguese","currencies":"Cape Verdean escudo","borders":"","summary":"Cape Verde, also referred to in English by its Portuguese name Cabo Verde, and known officially as the Republic of Cabo Verde, is an archipelagic country in the eastern Atlantic Ocean, off the coast of West Africa. It consists of ten volcanic islands with a combined land area of about 4,033 square kilometres (1,557 sq mi). These islands lie between 600 and 850 kilometres west of Cap-Vert, the westernmost point of continental Africa, after which they are named. Cape Verde forms part of the Macaronesia ecoregion, along with the Azores, the Canary Islands, Madeira and the Savage Islands.","currencyCode":"CVE"},{"name":"Costa Rica","officialName":"Republic of Costa Rica","nativeName":"Costa Rica","continent":"North America","region":"Americas","subregion":"Central America","capital":"San José","area":51100,"population":0,"languages":"Spanish","currencies":"Costa Rican colón","borders":"NIC, PAN","summary":"","currencyCode":"CRC"},{"name":"Cuba","officialName":"Republic of Cuba","nativeName":"Cuba","continent":"North America","region":"Americas","subregion":"Caribbean","capital":"Havana","area":109884,"population":0,"languages":"Spanish","currencies":"Cuban convertible peso, Cuban peso","borders":"","summary":"Cuba, officially the Republic of Cuba, is an island country in the Caribbean. It comprises the eponymous main island as well as 4,195 islands, islets, and cays. Situated at the convergence of the Caribbean Sea, Gulf of Mexico, and Atlantic Ocean, Cuba is located east of the Yucatán Peninsula, south of both Florida and the Bahamas, west of Hispaniola, and north of Jamaica and the Cayman Islands. Cuba is the largest country in the Caribbean by area and the third-largest by population, after Haiti and the Dominican Republic. Culturally, Cuba is considered to be part of Latin America. Its capital and largest city is Havana.","currencyCode":"CUC"},{"name":"Cyprus","officialName":"Republic of Cyprus","nativeName":"Κύπρος","continent":"Europe","region":"Europe","subregion":"Southern Europe","capital":"Nicosia","area":9251,"population":0,"languages":"Greek, Turkish","currencies":"Euro","borders":"","summary":"","currencyCode":"EUR"},{"name":"Czechia","officialName":"Czech Republic","nativeName":"Česko","continent":"Europe","region":"Europe","subregion":"Central Europe","capital":"Prague","area":78865,"population":0,"languages":"Czech, Slovak","currencies":"Czech koruna","borders":"AUT, DEU, POL, SVK","summary":"","currencyCode":"CZK"},{"name":"Germany","officialName":"Federal Republic of Germany","nativeName":"Deutschland","continent":"Europe","region":"Europe","subregion":"Western Europe","capital":"Berlin","area":357114,"population":0,"languages":"German","currencies":"Euro","borders":"AUT, BEL, CZE, DNK, FRA, LUX, NLD, POL, CHE","summary":"Germany, officially the Federal Republic of Germany, is a country in Western and Central Europe. It lies between the Baltic Sea and the North Sea to the north with the Alps to the south. Its 16 constituent states have a total population of over 83 million, making it the most populous member state of the European Union (EU). Germany borders Denmark to the north; Poland and the Czech Republic to the east; Austria and Switzerland to the south; and France, Luxembourg, Belgium, and the Netherlands to the west. The nation's capital and most populous city is Berlin and its main financial centre is Frankfurt; the largest urban area is the Ruhr.","currencyCode":"EUR"},{"name":"Djibouti","officialName":"Republic of Djibouti","nativeName":"جيبوتي","continent":"Africa","region":"Africa","subregion":"Eastern Africa","capital":"Djibouti","area":23200,"population":0,"languages":"Arabic, French","currencies":"Djiboutian franc","borders":"ERI, ETH, SOM","summary":"","currencyCode":"DJF"},{"name":"Dominica","officialName":"Commonwealth of Dominica","nativeName":"Dominica","continent":"North America","region":"Americas","subregion":"Caribbean","capital":"Roseau","area":751,"population":0,"languages":"English","currencies":"Eastern Caribbean dollar","borders":"","summary":"","currencyCode":"XCD"},{"name":"Denmark","officialName":"Kingdom of Denmark","nativeName":"Danmark","continent":"Europe","region":"Europe","subregion":"Northern Europe","capital":"Copenhagen","area":43094,"population":0,"languages":"Danish","currencies":"Danish krone","borders":"DEU","summary":"Denmark is a Nordic country in Northern Europe. It is the metropole and most populous constituent of the Kingdom of Denmark, also known as the Danish Realm, a constitutionally unitary state that includes the autonomous territories of the Faroe Islands and Greenland in the north Atlantic Ocean. Metropolitan Denmark, also called \"continental Denmark\" or \"Denmark proper\", consists of the northern Jutland peninsula and an archipelago of 406 islands. It is the southernmost of the Scandinavian countries, lying southwest of Sweden, south of Norway, and north of Germany, with which it shares a short border. Metropolitan Denmark is situated between the North Sea to the west and the Baltic Sea to the east.","currencyCode":"DKK"},{"name":"Dominican Republic","officialName":"Dominican Republic","nativeName":"República Dominicana","continent":"North America","region":"Americas","subregion":"Caribbean","capital":"Santo Domingo","area":48671,"population":0,"languages":"Spanish","currencies":"Dominican peso","borders":"HTI","summary":"The Dominican Republic is an island country on the eastern part of the Caribbean island of Hispaniola in the Greater Antilles of the Caribbean Sea in the North Atlantic Ocean. It shares a maritime border with Puerto Rico to the east and a land border with Haiti to the west, occupying the eastern five-eighths of Hispaniola which, along with Saint Martin, is one of only two islands in the Caribbean shared by two sovereign states. In the Antilles, the country is the second-largest by area after Cuba at 48,671 square kilometers (18,792 sq mi) and the second most populous after Haiti with approximately 11.4 million people in 2024, of whom 3.6 million reside in the metropolitan area of Santo Domingo, the capital city.","currencyCode":"DOP"},{"name":"Algeria","officialName":"People's Democratic Republic of Algeria","nativeName":"الجزائر","continent":"Africa","region":"Africa","subregion":"Northern Africa","capital":"Algiers","area":2381741,"population":0,"languages":"Arabic","currencies":"Algerian dinar","borders":"TUN, LBY, NER, ESH, MRT, MLI, MAR","summary":"Algeria, officially the People's Democratic Republic of Algeria, is a country in the Maghreb region of North Africa. Spanning over 2,381,741 square kilometres (919,595 sq mi), it is the largest country in Africa and the tenth largest in the world. It is bordered to the northeast by Tunisia; to the east by Libya; to the southeast by Niger; to the southwest by Mali, Mauritania, and Western Sahara; to the west by Morocco; and to the north by the Mediterranean Sea. With a population of over 47 million, Algeria is the tenth-most populous country in Africa. Its capital and largest city is Algiers.","currencyCode":"DZD"},{"name":"Ecuador","officialName":"Republic of Ecuador","nativeName":"Ecuador","continent":"South America","region":"Americas","subregion":"South America","capital":"Quito","area":276841,"population":0,"languages":"Spanish","currencies":"United States dollar","borders":"COL, PER","summary":"","currencyCode":"USD"},{"name":"Egypt","officialName":"Arab Republic of Egypt","nativeName":"مصر","continent":"Africa","region":"Africa","subregion":"Northern Africa","capital":"Cairo","area":1002450,"population":0,"languages":"Arabic","currencies":"Egyptian pound","borders":"ISR, LBY, PSE, SDN","summary":"Egypt, officially the Arab Republic of Egypt, is a country spanning the northeast corner of Africa and southwest corner of Asia via the Sinai Peninsula. It is bordered by the Mediterranean Sea to the north, Palestine and Israel to the northeast, the Red Sea to the east, Sudan and the Sahara to the south, and Libya to the west. The Gulf of Aqaba in the northeast separates Egypt from Jordan and Saudi Arabia. Cairo is the capital, largest city, and leading cultural centre, while Alexandria is the second-largest city and an important hub of industry and tourism. With over 107 million inhabitants, Egypt is the most populous country in the Arab world, third-most populous country in Africa, and 15th-most populated in the world.","currencyCode":"EGP"},{"name":"Eritrea","officialName":"State of Eritrea","nativeName":"إريتريا","continent":"Africa","region":"Africa","subregion":"Eastern Africa","capital":"Asmara","area":117600,"population":0,"languages":"Arabic, English, Tigrinya","currencies":"Eritrean nakfa","borders":"DJI, ETH, SDN","summary":"","currencyCode":"ERN"},{"name":"Spain","officialName":"Kingdom of Spain","nativeName":"España","continent":"Europe","region":"Europe","subregion":"Southern Europe","capital":"Madrid","area":505992,"population":0,"languages":"Spanish","currencies":"Euro","borders":"AND, FRA, GIB, PRT, MAR","summary":"Spain, officially the Kingdom of Spain, is a country in Southern and Western Europe with territories in North Africa. Featuring the southernmost point of continental Europe, it is the largest country in Southern Europe and the fourth-most populous European Union (EU) member state. Spanning the majority of the Iberian Peninsula, its territory also includes the Canary Islands, in the Eastern Atlantic Ocean; the Balearic Islands, in the Western Mediterranean Sea; and the autonomous cities of Ceuta and Melilla, in mainland Africa. Peninsular Spain is bordered to the north by France, Andorra, and the Bay of Biscay; to the east and south by the Mediterranean Sea, Gibraltar and Morocco ; and to the west by Portugal and the Atlantic Ocean. Spain's capital and largest city is Madrid; other major urban areas include Barcelona, Valencia, Zaragoza, Seville, Bilbao, Málaga, Murcia, Palma de Mallorca and Las Palmas.","currencyCode":"EUR"},{"name":"Estonia","officialName":"Republic of Estonia","nativeName":"Eesti","continent":"Europe","region":"Europe","subregion":"Northern Europe","capital":"Tallinn","area":45227,"population":0,"languages":"Estonian","currencies":"Euro","borders":"LVA, RUS","summary":"Estonia, officially the Republic of Estonia, is a country in the Baltic region of Northern Europe. It is bordered to the north by the Gulf of Finland across from Finland, to the west by the Baltic Sea across from Sweden, to the south by Latvia, and to the east by Russia. The territory of Estonia consists of the mainland, the larger islands of Saaremaa and Hiiumaa, and over 2,300 other islands and islets on the east coast of the Baltic Sea. Its capital city of Tallinn, along with the city of Tartu, are the country's two largest urban areas. The Estonian language, of the Finnic family, is the official language and the first language of the majority of nearly 1.4 million people. Estonia is one of the least populous member states of the European Union.","currencyCode":"EUR"},{"name":"Ethiopia","officialName":"Federal Democratic Republic of Ethiopia","nativeName":"ኢትዮጵያ","continent":"Africa","region":"Africa","subregion":"Eastern Africa","capital":"Addis Ababa","area":1104300,"population":0,"languages":"Amharic","currencies":"Ethiopian birr","borders":"DJI, ERI, KEN, SOM, SSD, SDN","summary":"Ethiopia, officially the Federal Democratic Republic of Ethiopia (FDRE), is a landlocked country located in the Horn of Africa region of East Africa. It shares borders with Eritrea to the north, Djibouti to the northeast, Somalia to the southeast, Kenya to the south, South Sudan to the west, and Sudan to the northwest. Ethiopia covers a land area of 1,104,300 km2 (426,400 sq mi). As of 2026, it has around 138 million inhabitants, making it the 10th-most populous country in the world and 2nd most populous country in Africa. The national capital and largest city, Addis Ababa, lies several kilometres west of the East African Rift that splits the country into the African and Somali tectonic plates.","currencyCode":"ETB"},{"name":"Finland","officialName":"Republic of Finland","nativeName":"Suomi","continent":"Europe","region":"Europe","subregion":"Northern Europe","capital":"Helsinki","area":338424,"population":0,"languages":"Finnish, Swedish","currencies":"Euro","borders":"NOR, SWE, RUS","summary":"Finland, officially the Republic of Finland, is a Nordic country in Northern Europe. It borders Sweden to the northwest, Norway to the north, and Russia to the east, with the Gulf of Bothnia to the west and the Gulf of Finland to the south, opposite Estonia. Its capital and largest city is Helsinki. Finland has a population of 5.7 million. The official languages are Finnish and Swedish, the mother tongues of 83.5 percent and 5.0 percent of the population, respectively. Finland's climate varies from humid continental in the south to boreal in the north. Its land is predominantly covered by boreal forest, with over 180,000 recorded lakes.","currencyCode":"EUR"},{"name":"Fiji","officialName":"Republic of Fiji","nativeName":"Fiji","continent":"Oceania","region":"Oceania","subregion":"Melanesia","capital":"Suva","area":18272,"population":0,"languages":"English, Fijian, Fiji Hindi","currencies":"Fijian dollar","borders":"","summary":"Fiji, officially the Republic of Fiji, is an archipelagic country in Melanesia, part of Oceania in the South Pacific Ocean. It lies about 1,100 nautical miles north-northeast of New Zealand. Fiji consists of an archipelago of more than 330 islands—of which about 110 are permanently inhabited—and more than 500 islets, amounting to a total land area of about 18,300 square kilometres (7,100 sq mi). The most outlying island group is Ono-i-Lau. About 87% of the total population live on the two major islands, Viti Levu and Vanua Levu. About three-quarters of Fijians live on Viti Levu's coasts, either in the capital city of Suva, or in smaller urban centres such as Nadi or Lautoka. The interior of Viti Levu is sparsely inhabited because of its terrain.","currencyCode":"FJD"},{"name":"France","officialName":"French Republic","nativeName":"France","continent":"Europe","region":"Europe","subregion":"Western Europe","capital":"Paris","area":551695,"population":0,"languages":"French","currencies":"Euro","borders":"AND, BEL, DEU, ITA, LUX, MCO, ESP, CHE","summary":"France, officially the French Republic, is a country primarily located in Western Europe. Its overseas regions and territories include French Guiana in South America, Saint Pierre and Miquelon in the North Atlantic, the French West Indies, and many islands in Oceania and the Indian Ocean. Metropolitan France shares borders with Belgium and Luxembourg to the north; Germany to the northeast; Switzerland to the east; Italy and Monaco to the southeast; Andorra and Spain to the south; and a maritime border with the United Kingdom to the northwest. Its metropolitan area extends from the Rhine to the Atlantic Ocean and from the Mediterranean Sea to the English Channel and the North Sea. Its 18 integral regions—five of which are overseas—span a combined area of 632,702 km2 (244,288 sq mi), with a total population estimated at over 69.1 million in 2026. Its capital, largest city and main cultural and economic centre is Paris, with a metropolitan population of over 13 million.","currencyCode":"EUR"},{"name":"Micronesia","officialName":"Federated States of Micronesia","nativeName":"Micronesia","continent":"Oceania","region":"Oceania","subregion":"Micronesia","capital":"Palikir","area":702,"population":0,"languages":"English","currencies":"","borders":"","summary":"","currencyCode":""},{"name":"Gabon","officialName":"Gabonese Republic","nativeName":"Gabon","continent":"Africa","region":"Africa","subregion":"Middle Africa","capital":"Libreville","area":267668,"population":0,"languages":"French","currencies":"Central African CFA franc","borders":"CMR, COG, GNQ","summary":"Gabon, officially the Gabonese Republic, is a country on the Atlantic coast of Central Africa, lying on the equator. It is bordered by Equatorial Guinea to the northwest, Cameroon to the north, the Republic of the Congo to the east and south, while sharing a maritime border with São Tomé and Príncipe to the west in the Gulf of Guinea. It has an area of 270,000 square kilometres (100,000 sq mi) and a population of 2.6 million people. There are coastal plains, mountains, and savanna in the east. Libreville is the capital and largest city; other major cities include Port-Gentil and Franceville.","currencyCode":"XAF"},{"name":"United Kingdom","officialName":"United Kingdom of Great Britain and Northern Ireland","nativeName":"United Kingdom","continent":"Europe","region":"Europe","subregion":"Northern Europe","capital":"London","area":242900,"population":0,"languages":"English","currencies":"British pound","borders":"IRL","summary":"The United Kingdom of Great Britain and Northern Ireland, commonly known as the United Kingdom (UK) or Britain, is a country in northwestern Europe, off the coast of the continental mainland. It comprises England, Scotland, Wales and Northern Ireland, with a population of over 69 million in 2024. The UK includes the island of Great Britain, the north-eastern part of the island of Ireland, and most of the smaller islands within the British Isles, covering 94,354 square miles (244,376 km2). It shares a land border with the Republic of Ireland and is surrounded by the Atlantic Ocean, the North Sea, the English Channel, the Celtic Sea and the Irish Sea, while maintaining sovereignty over the Crown Dependencies and the British Overseas Territories. The capital and largest city of England and the UK is London; Edinburgh, Cardiff and Belfast are the national capitals of Scotland, Wales and Northern Ireland, respectively.","currencyCode":"GBP"},{"name":"Georgia","officialName":"Georgia","nativeName":"საქართველო","continent":"Asia","region":"Asia","subregion":"Western Asia","capital":"Tbilisi","area":69700,"population":0,"languages":"Georgian","currencies":"lari","borders":"ARM, AZE, RUS, TUR","summary":"","currencyCode":"GEL"},{"name":"Ghana","officialName":"Republic of Ghana","nativeName":"Ghana","continent":"Africa","region":"Africa","subregion":"Western Africa","capital":"Accra","area":238533,"population":0,"languages":"English","currencies":"Ghanaian cedi","borders":"BFA, CIV, TGO","summary":"","currencyCode":"GHS"},{"name":"Guinea","officialName":"Republic of Guinea","nativeName":"Guinée","continent":"Africa","region":"Africa","subregion":"Western Africa","capital":"Conakry","area":245857,"population":0,"languages":"French","currencies":"Guinean franc","borders":"CIV, GNB, LBR, MLI, SEN, SLE","summary":"Guinea, officially the Republic of Guinea, is a coastal country located in West Africa. It borders the Atlantic Ocean to the west, Guinea-Bissau to the northwest, Senegal to the north, Mali to the northeast, Ivory Coast to the southeast, and Sierra Leone and Liberia to the south. It is sometimes referred to as Guinea-Conakry, after its capital Conakry, to distinguish it from other territories in the eponymous region, such as Guinea-Bissau and Equatorial Guinea. At the census held on 1 July 2025, Guinea had a population of over 17.5 million and an area of 245,857 square kilometres (94,926 sq mi).","currencyCode":"GNF"},{"name":"Gambia","officialName":"Republic of the Gambia","nativeName":"Gambia","continent":"Africa","region":"Africa","subregion":"Western Africa","capital":"Banjul","area":10689,"population":0,"languages":"English","currencies":"dalasi","borders":"SEN","summary":"","currencyCode":"GMD"},{"name":"Guinea-Bissau","officialName":"Republic of Guinea-Bissau","nativeName":"Guiné-Bissau","continent":"Africa","region":"Africa","subregion":"Western Africa","capital":"Bissau","area":36125,"population":0,"languages":"Portuguese, Upper Guinea Creole","currencies":"West African CFA franc","borders":"GIN, SEN","summary":"","currencyCode":"XOF"},{"name":"Equatorial Guinea","officialName":"Republic of Equatorial Guinea","nativeName":"Guinée équatoriale","continent":"Africa","region":"Africa","subregion":"Middle Africa","capital":"Malabo","area":28051,"population":0,"languages":"French, Portuguese, Spanish","currencies":"Central African CFA franc","borders":"CMR, GAB","summary":"","currencyCode":"XAF"},{"name":"Greece","officialName":"Hellenic Republic","nativeName":"Ελλάδα","continent":"Europe","region":"Europe","subregion":"Southern Europe","capital":"Athens","area":131990,"population":0,"languages":"Greek","currencies":"Euro","borders":"ALB, BGR, TUR, MKD","summary":"Greece, officially the Hellenic Republic, is a country in Southeastern Europe. It occupies the southern tip of the Balkan peninsula, with a population of around 10 million. With nine regions and thousands of islands, it has the longest coastline on the Mediterranean. The Ionian Sea is west of the mainland, Albania northwest, and North Macedonia and Bulgaria north. Turkey is east both by land and the Aegean Sea. The capital, Athens, is the largest Greek city, followed by Thessaloniki and Patras.","currencyCode":"EUR"},{"name":"Grenada","officialName":"Grenada","nativeName":"Grenada","continent":"North America","region":"Americas","subregion":"Caribbean","capital":"St. George's","area":344,"population":0,"languages":"English","currencies":"Eastern Caribbean dollar","borders":"","summary":"Grenada is an archipelagic country of the West Indies in the eastern Caribbean Sea. The southernmost of the Windward Islands, Grenada is directly south of Saint Vincent and the Grenadines and about 100 miles (160 km) north of Trinidad and the South American mainland.","currencyCode":"XCD"},{"name":"Guatemala","officialName":"Republic of Guatemala","nativeName":"Guatemala","continent":"North America","region":"Americas","subregion":"Central America","capital":"Guatemala City","area":108889,"population":0,"languages":"Spanish","currencies":"Guatemalan quetzal","borders":"BLZ, SLV, HND, MEX","summary":"Guatemala, officially the Republic of Guatemala, is a country in northern Central America. It is bordered to the north and west by Mexico, to the northeast by Belize, to the east by Honduras, and to the southeast by El Salvador. It is bounded by the Pacific Ocean to the south and the Gulf of Honduras to the northeast.","currencyCode":"GTQ"},{"name":"Guyana","officialName":"Co-operative Republic of Guyana","nativeName":"Guyana","continent":"South America","region":"Americas","subregion":"South America","capital":"Georgetown","area":214969,"population":0,"languages":"English","currencies":"Guyanese dollar","borders":"BRA, SUR, VEN","summary":"Guyana, officially the Co-operative Republic of Guyana, is a country on the northern coast of South America. It is bordered by the Atlantic Ocean to the north, Suriname to the east, Brazil to the south and southwest, and Venezuela to the west. It is part of the Guianas. The capital and largest city is Georgetown.","currencyCode":"GYD"},{"name":"Honduras","officialName":"Republic of Honduras","nativeName":"Honduras","continent":"North America","region":"Americas","subregion":"Central America","capital":"Tegucigalpa","area":112492,"population":0,"languages":"Spanish","currencies":"Honduran lempira","borders":"GTM, SLV, NIC","summary":"Honduras, officially the Republic of Honduras, is a country in Central America. It is bordered to the west by Guatemala, to the southwest by El Salvador, to the southeast by Nicaragua, to the south by the Pacific Ocean at the Gulf of Fonseca, and to the north by the Gulf of Honduras, a large inlet of the Caribbean Sea. Its capital and largest city is Tegucigalpa.","currencyCode":"HNL"},{"name":"Croatia","officialName":"Republic of Croatia","nativeName":"Hrvatska","continent":"Europe","region":"Europe","subregion":"Southeast Europe","capital":"Zagreb","area":56594,"population":0,"languages":"Croatian","currencies":"Euro","borders":"BIH, HUN, MNE, SRB, SVN","summary":"Croatia, officially the Republic of Croatia, is a country in Central and Southeastern Europe, on the coast of the Adriatic Sea. It borders Slovenia to the northwest, Hungary to the northeast, Serbia to the east, Bosnia and Herzegovina and Montenegro to the southeast, and shares a maritime border with Italy to the west. The Croatian archipelago contains over 1,000 islands and islets, the largest overseas territory on the Adriatic Sea. Its capital, largest city and main cultural and economic centre is Zagreb. Major urban centers include Split, Rijeka, and Osijek. The country is composed of twenty counties spanning 56,594 square kilometres within four administrative regions. Croatia has a population of nearly 3.9 million as of 2026.","currencyCode":"EUR"},{"name":"Haiti","officialName":"Republic of Haiti","nativeName":"Haïti","continent":"North America","region":"Americas","subregion":"Caribbean","capital":"Port-au-Prince","area":27750,"population":0,"languages":"French, Haitian Creole","currencies":"Haitian gourde","borders":"DOM","summary":"Haiti, officially the Republic of Haiti, is a country in the Caribbean on the island of Hispaniola in the Caribbean Sea, east of Cuba and Jamaica and south of The Bahamas. It occupies the western side of the island, which it shares with the Dominican Republic. Haiti is the third largest country in the Caribbean by area, and with an estimated population of 11.4 million, it is the most populous Caribbean country. The capital and largest city is Port-au-Prince.","currencyCode":"HTG"},{"name":"Hungary","officialName":"Hungary","nativeName":"Magyarország","continent":"Europe","region":"Europe","subregion":"Central Europe","capital":"Budapest","area":93028,"population":0,"languages":"Hungarian","currencies":"Hungarian forint","borders":"AUT, HRV, ROU, SRB, SVK, SVN, UKR","summary":"","currencyCode":"HUF"},{"name":"Indonesia","officialName":"Republic of Indonesia","nativeName":"Indonesia","continent":"Asia","region":"Asia","subregion":"South-Eastern Asia","capital":"Jakarta","area":1904569,"population":0,"languages":"Indonesian","currencies":"Indonesian rupiah","borders":"TLS, MYS, PNG","summary":"Indonesia, officially the Republic of Indonesia, is a country in Southeast Asia and Oceania, between the Indian and Pacific oceans. Comprising between 13,000 and 17,000 islands, including Sumatra, Java, Sulawesi, and parts of Borneo and New Guinea, it is the world's largest archipelagic state and the 14th-largest country by area. Indonesia has extensive tropical forests and marine ecosystems that support one of the world's highest levels of biodiversity.","currencyCode":"IDR"},{"name":"India","officialName":"Republic of India","nativeName":"India","continent":"Asia","region":"Asia","subregion":"Southern Asia","capital":"New Delhi","area":3287590,"population":0,"languages":"English, Hindi, Tamil","currencies":"Indian rupee","borders":"BGD, BTN, MMR, CHN, NPL, PAK","summary":"India, officially the Republic of India, is a country in South Asia. It is the world's seventh-largest country by area and the largest by population. Bounded by the Indian Ocean on the south, the Arabian Sea on the southwest, and the Bay of Bengal on the southeast, it shares land borders with Pakistan to the west; China, Nepal, and Bhutan to the north; and Bangladesh and Myanmar to the east. In the Indian Ocean, India is near Sri Lanka and the Maldives.","currencyCode":"INR"},{"name":"Ireland","officialName":"Republic of Ireland","nativeName":"Ireland","continent":"Europe","region":"Europe","subregion":"Northern Europe","capital":"Dublin","area":70273,"population":0,"languages":"English, Irish","currencies":"Euro","borders":"GBR","summary":"","currencyCode":"EUR"},{"name":"Iran","officialName":"Islamic Republic of Iran","nativeName":"ایران","continent":"Asia","region":"Asia","subregion":"Southern Asia","capital":"Tehran","area":1648195,"population":0,"languages":"Persian (Farsi)","currencies":"Iranian rial","borders":"AFG, ARM, AZE, IRQ, PAK, TUR, TKM","summary":"Iran, officially the Islamic Republic of Iran, and historically known as Persia, is a country in West Asia. It borders Iraq to the west; Turkey, Azerbaijan, and Armenia to the northwest; the Caspian Sea to the north, Turkmenistan to the northeast; Afghanistan to the east; Pakistan to the southeast; and the Gulf of Oman and the Persian Gulf to the south. With a population of over 92 million, Iran ranks 17th globally in both geographic size and population. It is divided into five regions with 31 provinces. Tehran is the nation's capital and largest city and serves as its primary economic center.","currencyCode":"IRR"},{"name":"Iraq","officialName":"Republic of Iraq","nativeName":"العراق","continent":"Asia","region":"Asia","subregion":"Western Asia","capital":"Baghdad","area":438317,"population":0,"languages":"Arabic, Aramaic, Sorani","currencies":"Iraqi dinar","borders":"IRN, JOR, KWT, SAU, SYR, TUR","summary":"Iraq, officially the Republic of Iraq, historically known in the west as Mesopotamia, is a country in West Asia. Located within the Middle East, it is bordered by Saudi Arabia to the south, Turkey to the north, Iran to the east, the Persian Gulf and Kuwait to the southeast, Jordan to the southwest, and Syria to the west. The country covers an area of 438,317 square kilometres (169,235 sq mi) and has a population of over 46 million, making it the 58th largest country by area and the 31st most populous in the world. Baghdad, home to over 8 million people, is the capital city and the largest in the country.","currencyCode":"IQD"},{"name":"Iceland","officialName":"Iceland","nativeName":"Ísland","continent":"Europe","region":"Europe","subregion":"Northern Europe","capital":"Reykjavik","area":103000,"population":0,"languages":"Icelandic","currencies":"Icelandic króna","borders":"","summary":"Iceland is a Nordic island country between the Arctic Ocean and the North Atlantic Ocean, located on the Mid-Atlantic Ridge between Europe and North America. It is Europe's westernmost and most sparsely populated country. Its capital and largest city is Reykjavík, which is home to about 35% of the country's roughly 395,000 residents. The official language of the country is Icelandic. Iceland is on a rift between tectonic plates, and its geologic activity includes geysers and frequent volcanic eruptions. The interior consists of a volcanic plateau with sand and lava fields, mountains and glaciers, and many glacial rivers flow to the sea through the lowlands. Iceland is warmed by the Gulf Stream and has a temperate climate, despite being at a latitude just south of the Arctic Circle. Its latitude and marine influence keep summers chilly, and most of its islands have a polar climate.","currencyCode":"ISK"},{"name":"Israel","officialName":"State of Israel","nativeName":"إسرائيل","continent":"Asia","region":"Asia","subregion":"Western Asia","capital":"Jerusalem","area":20770,"population":0,"languages":"Arabic, Hebrew","currencies":"Israeli new shekel","borders":"EGY, JOR, LBN, PSE, SYR","summary":"Israel, officially the State of Israel, is a country in the Southern Levant region of West Asia. It is bordered by Lebanon to the north, Syria to the northeast, Jordan to the east, and Egypt to the southwest. Israel's western coast lies on the Mediterranean Sea, its southern tip reaches the Red Sea, and to the east is Earth's lowest point near the Dead Sea. Jerusalem is the government seat and proclaimed capital, while Tel Aviv is Israel's largest urban area and economic centre.","currencyCode":"ILS"},{"name":"Italy","officialName":"Italian Republic","nativeName":"Italia","continent":"Europe","region":"Europe","subregion":"Southern Europe","capital":"Rome","area":301336,"population":0,"languages":"Italian","currencies":"Euro","borders":"AUT, FRA, SMR, SVN, CHE, VAT","summary":"Italy, officially the Italian Republic, is a country in Southern and Western Europe. It consists of a peninsula, which extends into the Mediterranean Sea, with the Alps on its northern land border, as well as nearly 800 islands, notably Sicily and Sardinia. Italy shares land borders with France to the west; Switzerland and Austria to the north; Slovenia to the east; and the two enclaves of Vatican City and San Marino. It is the tenth-largest country in Europe by area, covering 301,340 km2 (116,350 sq mi), and the third-most populous member state of the European Union, with nearly 59 million inhabitants. Rome is the capital of Italy; other major cities include Milan, Naples, Turin, Palermo, Bologna, Florence, Genoa, Bari, and Venice.","currencyCode":"EUR"},{"name":"Jamaica","officialName":"Jamaica","nativeName":"Jamaica","continent":"North America","region":"Americas","subregion":"Caribbean","capital":"Kingston","area":10991,"population":0,"languages":"English, Jamaican Patois","currencies":"Jamaican dollar","borders":"","summary":"Jamaica is an island country in the Caribbean, covering 10,991 square kilometres (4,244 sq mi). It is the third-largest island in the Greater Antilles and the Caribbean, after Cuba and the island of Hispaniola. Jamaica lies about 145 km (78 nmi) south of Cuba, 191 km (103 nmi) west of Hispaniola, and 215 km (116 nmi) southeast of the Cayman Islands. With 2.8 million people, Jamaica is the third-most populous Anglophone country in the Americas and the fourth-most populous country in the Caribbean. Kingston is the capital and largest city.","currencyCode":"JMD"},{"name":"Jordan","officialName":"Hashemite Kingdom of Jordan","nativeName":"الأردن","continent":"Asia","region":"Asia","subregion":"Western Asia","capital":"Amman","area":89342,"population":0,"languages":"Arabic","currencies":"Jordanian dinar","borders":"IRQ, ISR, PSE, SAU, SYR","summary":"","currencyCode":"JOD"},{"name":"Japan","officialName":"Japan","nativeName":"日本","continent":"Asia","region":"Asia","subregion":"Eastern Asia","capital":"Tokyo","area":377930,"population":0,"languages":"Japanese","currencies":"Japanese yen","borders":"","summary":"Japan is an island country in East Asia. Located in the Pacific Ocean off the northeast coast of the Asian mainland, it is bordered to the west by the Sea of Japan, the Sea of Okhotsk in the north, and the East China Sea in the south. The Japanese archipelago consists of four major islands alongside over 14,000 smaller islands. Japan is divided into 47 administrative prefectures and eight traditional regions, and around 75% of its terrain is mountainous and heavily forested, concentrating its agriculture and highly urbanized population along its eastern coastal plains. With a population of almost 123 million as of 2026, it is the world's 11th most populous country. Tokyo is the country's capital and largest city.","currencyCode":"JPY"},{"name":"Kazakhstan","officialName":"Republic of Kazakhstan","nativeName":"Қазақстан","continent":"Asia","region":"Asia","subregion":"Central Asia","capital":"Astana","area":2724900,"population":0,"languages":"Kazakh, Russian","currencies":"Kazakhstani tenge","borders":"CHN, KGZ, RUS, TKM, UZB","summary":"Kazakhstan, officially the Republic of Kazakhstan, is a landlocked country situated primarily in Central Asia, with a portion of its territory extending into Eastern Europe. It borders Russia to the north and west, China to the east, Kyrgyzstan to the southeast, Uzbekistan to the south, and Turkmenistan to the southwest, and it has a coastline along the Caspian Sea. The capital is Astana, and the country's largest city and principal cultural and economic center is Almaty, which served as the capital until 1997.","currencyCode":"KZT"},{"name":"Kenya","officialName":"Republic of Kenya","nativeName":"Kenya","continent":"Africa","region":"Africa","subregion":"Eastern Africa","capital":"Nairobi","area":580367,"population":0,"languages":"English, Swahili","currencies":"Kenyan shilling","borders":"ETH, SOM, SSD, TZA, UGA","summary":"Kenya, officially the Republic of Kenya, is a country located in East Africa. With an estimated population of more than 54.2 million as of mid-2026, it is the 26th-most populous country in the world and the seventh-most populous in Africa. Kenya's capital and largest city is Nairobi. The second-largest and oldest city is Mombasa, a port city located on Mombasa Island. Other major cities within the country include Kisumu, Nakuru and Eldoret. Going clockwise, Kenya is bordered by South Sudan to the northwest, Ethiopia to the north, Somalia to the east, the Indian Ocean to the southeast, Tanzania to the southwest, and Lake Victoria and Uganda to the west. Its geography, climate and population vary. In western Rift Valley counties, the landscape includes cold, snow-capped mountaintops with surrounding forests, wildlife, and fertile agricultural regions in temperate climates. In other areas there are dry, arid, and semi-arid climates, as well as absolute deserts.","currencyCode":"KES"},{"name":"Kyrgyzstan","officialName":"Kyrgyz Republic","nativeName":"Кыргызстан","continent":"Asia","region":"Asia","subregion":"Central Asia","capital":"Bishkek","area":199951,"population":0,"languages":"Kyrgyz, Russian","currencies":"Kyrgyzstani som","borders":"CHN, KAZ, TJK, UZB","summary":"Kyrgyzstan, officially the Kyrgyz Republic, formerly known as Kirghizia, is a landlocked country located in Central Asia, lying in the Tian Shan and Pamir mountain ranges. It is bordered by Kazakhstan to the north, Uzbekistan to the west, Tajikistan to the south, and China to the east and southeast. The capital and largest city is Bishkek which lies on the northern border with Kazakhstan. Ethnic Kyrgyz make up the majority of the 7.5 million people, followed by significant minorities of Uzbeks and Russians.","currencyCode":"KGS"},{"name":"Cambodia","officialName":"Kingdom of Cambodia","nativeName":"Kâmpŭchéa","continent":"Asia","region":"Asia","subregion":"South-Eastern Asia","capital":"Phnom Penh","area":181035,"population":0,"languages":"Khmer","currencies":"Cambodian riel, United States dollar","borders":"LAO, THA, VNM","summary":"Cambodia, officially the Kingdom of Cambodia, is a country in Mainland Southeast Asia. It is bordered by Thailand to the northwest, Laos to the north, and Vietnam to the east, and has a coastline along the Gulf of Thailand in the southwest. It spans an area of about 181,035 km2 (69,898 sq mi), dominated by a low-lying plain and the confluence of the Mekong river and Tonlé Sap, Southeast Asia's largest lake. It is dominated by a tropical climate. Cambodia has a population of about 17 million people, the majority of which are ethnically Khmer. Its capital and most populous city is Phnom Penh, followed by Siem Reap and Battambang.","currencyCode":"KHR"},{"name":"Kiribati","officialName":"Independent and Sovereign Republic of Kiribati","nativeName":"Kiribati","continent":"Oceania","region":"Oceania","subregion":"Micronesia","capital":"South Tarawa","area":811,"population":0,"languages":"English, Gilbertese","currencies":"Australian dollar, Kiribati dollar","borders":"","summary":"Kiribati, officially the Republic of Kiribati, is an archipelagic country spanning the Micronesia and Polynesia sub-regions of Oceania in the central Pacific Ocean. The state comprises 32 atolls and other islands and one remote raised coral island, Banaba. Its total land area is 811 km2 (313 sq mi) dispersed over 3,441,810 km2 (1,328,890 sq mi) of ocean. The spread of the country's islands, from Banaba in the west to Kiritimati in the east, straddles the equator and the 180th meridian. The International Date Line goes around Kiribati and swings far to the east, almost reaching 150°W. This brings Kiribati's easternmost islands, the southern Line Islands south of Hawaii, into the same day as the Gilbert Islands and places them in the most advanced time zone on Earth: UTC+14.","currencyCode":"AUD"},{"name":"Saint Kitts and Nevis","officialName":"Federation of Saint Christopher and Nevis","nativeName":"Saint Kitts and Nevis","continent":"North America","region":"Americas","subregion":"Caribbean","capital":"Basseterre","area":261,"population":0,"languages":"English","currencies":"Eastern Caribbean dollar","borders":"","summary":"","currencyCode":"XCD"},{"name":"South Korea","officialName":"Republic of Korea","nativeName":"한국","continent":"Asia","region":"Asia","subregion":"Eastern Asia","capital":"Seoul","area":100210,"population":0,"languages":"Korean","currencies":"South Korean won","borders":"PRK","summary":"South Korea, officially the Republic of Korea (ROK), is a country in East Asia. It constitutes the southern half of the Korean Peninsula and borders North Korea along the Korean Demilitarized Zone, with the Yellow Sea to the west and the Sea of Japan to the east. South Korea claims to be the sole legitimate government of the entire peninsula and adjacent islands. It has a population of about 52 million, of which half live in the Seoul metropolitan area, the ninth most populous metropolitan area in the world, with other major cities being Busan, Daegu, and Incheon.","currencyCode":"KRW"},{"name":"Kuwait","officialName":"State of Kuwait","nativeName":"الكويت","continent":"Asia","region":"Asia","subregion":"Western Asia","capital":"Kuwait City","area":17818,"population":0,"languages":"Arabic","currencies":"Kuwaiti dinar","borders":"IRQ, SAU","summary":"","currencyCode":"KWD"},{"name":"Laos","officialName":"Lao People's Democratic Republic","nativeName":"ສປປລາວ","continent":"Asia","region":"Asia","subregion":"South-Eastern Asia","capital":"Vientiane","area":236800,"population":0,"languages":"Lao","currencies":"Lao kip","borders":"MMR, KHM, CHN, THA, VNM","summary":"Laos, officially the Lao People's Democratic Republic (LPDR), is a country in Mainland Southeast Asia, and the only landlocked country in Southeast Asia. It is bordered by Myanmar and China to the northwest, Vietnam to the east, Cambodia to the southeast, and Thailand to the west and southwest. Laos has a population of more than 7.5 million, and its capital and most populous city is Vientiane. It has three UNESCO World Heritage Sites: the town of Luang Prabang, the temple complex of Vat Phou, and the Plain of Jars. Laos participates in the Greater Mekong Subregion economic cooperation programme and is a member of ASEAN, the Asia-Pacific Trade Agreement, East Asia Summit, La Francophonie, and the World Trade Organization.","currencyCode":"LAK"},{"name":"Lebanon","officialName":"Lebanese Republic","nativeName":"لبنان","continent":"Asia","region":"Asia","subregion":"Western Asia","capital":"Beirut","area":10452,"population":0,"languages":"Arabic, French","currencies":"Lebanese pound","borders":"ISR, SYR","summary":"Lebanon, officially the Lebanese Republic, is a country in the Levant region of West Asia. Situated at the crossroads of the Mediterranean Basin and the Arabian Peninsula, it is bordered by Syria to the north and east, Israel to the south, and the Mediterranean Sea to the west; Cyprus lies a short distance from the coastline. Lebanon has a population of more than five million and an area of 10,452 square kilometres (4,036 sq mi). Beirut is the country's capital and largest city.","currencyCode":"LBP"},{"name":"Liberia","officialName":"Republic of Liberia","nativeName":"Liberia","continent":"Africa","region":"Africa","subregion":"Western Africa","capital":"Monrovia","area":111369,"population":0,"languages":"English","currencies":"Liberian dollar","borders":"GIN, CIV, SLE","summary":"","currencyCode":"LRD"},{"name":"Libya","officialName":"State of Libya","nativeName":"ليبيا","continent":"Africa","region":"Africa","subregion":"Northern Africa","capital":"Tripoli","area":1759540,"population":0,"languages":"Arabic","currencies":"Libyan dinar","borders":"DZA, TCD, EGY, NER, SDN, TUN","summary":"Libya, officially the State of Libya, is a country in the Maghreb region of North Africa. It borders the Mediterranean Sea to the north, Egypt to the east, Sudan to the southeast, Chad to the south, Niger to the southwest, Algeria to the west, and Tunisia to the northwest. With an area of almost 1.8 million km2 (700,000 sq mi), Libya is the fourth-largest country in Africa and the Arab world, and the 16th-largest in the world. The country claims 32,000 square kilometres of southeastern Algeria, south of the Libyan town of Ghat. The capital and largest city is Tripoli, located in the northwest and containing over a million of Libya's seven million people.","currencyCode":"LYD"},{"name":"Saint Lucia","officialName":"Saint Lucia","nativeName":"Saint Lucia","continent":"North America","region":"Americas","subregion":"Caribbean","capital":"Castries","area":616,"population":0,"languages":"English","currencies":"Eastern Caribbean dollar","borders":"","summary":"","currencyCode":"XCD"},{"name":"Liechtenstein","officialName":"Principality of Liechtenstein","nativeName":"Liechtenstein","continent":"Europe","region":"Europe","subregion":"Western Europe","capital":"Vaduz","area":160,"population":0,"languages":"German","currencies":"Swiss franc","borders":"AUT, CHE","summary":"","currencyCode":"CHF"},{"name":"Sri Lanka","officialName":"Democratic Socialist Republic of Sri Lanka","nativeName":"ශ්‍රී ලංකාව","continent":"Asia","region":"Asia","subregion":"Southern Asia","capital":"Colombo","area":65610,"population":0,"languages":"Sinhala, Tamil","currencies":"Sri Lankan rupee","borders":"IND","summary":"Sri Lanka, officially the Democratic Socialist Republic of Sri Lanka, formerly known as Ceylon, is an island country in South Asia. It is located in the Indian Ocean, southwest of the Bay of Bengal, and is separated from India by the Gulf of Mannar and the Palk Strait. Sri Lanka shares a maritime border with the Maldives to the southwest and India to the northwest, and lies across the Bay of Bengal from Bangladesh and Myanmar to the northeast and the Andaman and Nicobar Islands of India to the east. Its executive and judicial capital is Colombo, which is also its largest city and the political, financial and cultural centre of the country; neighboring Sri Jayawardenepura Kotte is the legislative capital. Sri Lanka's population is 22 million. About 74% of the population are Sinhalese, who speak the Sinhala language, and about 15% are Tamils who speak the Tamil language. Other long-established ethnic groups include the Moors, Indian Tamils, Burghers, Malays, Chinese, and Vedda.","currencyCode":"LKR"},{"name":"Lesotho","officialName":"Kingdom of Lesotho","nativeName":"Lesotho","continent":"Africa","region":"Africa","subregion":"Southern Africa","capital":"Maseru","area":30355,"population":0,"languages":"English, Sotho","currencies":"Lesotho loti, South African rand","borders":"ZAF","summary":"Lesotho, officially the Kingdom of Lesotho, is a landlocked country in Southern Africa. Surrounded by South Africa, it is the largest of the three sovereign enclaves. Lesotho is located in the Maloti Mountains, with the highest peak in southern Africa. It has an area of over 30,000 km2 (11,600 mi2), with a population of about 2.3 million. Its capital and largest city is Maseru.","currencyCode":"LSL"},{"name":"Lithuania","officialName":"Republic of Lithuania","nativeName":"Lietuva","continent":"Europe","region":"Europe","subregion":"Northern Europe","capital":"Vilnius","area":65300,"population":0,"languages":"Lithuanian","currencies":"Euro","borders":"BLR, LVA, POL, RUS","summary":"","currencyCode":"EUR"},{"name":"Luxembourg","officialName":"Grand Duchy of Luxembourg","nativeName":"Luxemburg","continent":"Europe","region":"Europe","subregion":"Western Europe","capital":"Luxembourg","area":2586,"population":0,"languages":"German, French, Luxembourgish","currencies":"Euro","borders":"BEL, FRA, DEU","summary":"Luxembourg, officially the Grand Duchy of Luxembourg, is a landlocked country in Western Europe. It is bordered by Belgium to the west and north, Germany to the east, and France to the south and west. Its capital and most populous city, Luxembourg City, is one of the four institutional seats of the European Union and hosts several EU institutions, notably the Court of Justice of the European Union, the highest judicial authority in the EU.","currencyCode":"EUR"},{"name":"Latvia","officialName":"Republic of Latvia","nativeName":"Latvija","continent":"Europe","region":"Europe","subregion":"Northern Europe","capital":"Riga","area":64559,"population":0,"languages":"Latvian","currencies":"Euro","borders":"BLR, EST, LTU, RUS","summary":"Latvia, officially the Republic of Latvia, is a country in the Baltic region of northern Europe. It is one of the three Baltic states, along with Estonia to the north and Lithuania to the south. It borders Russia to the east and Belarus to the southeast and shares a maritime border with Sweden to the west. Latvia covers an area of 64,573 km2 (24,932 sq mi), with a population of 1.83 million. The country has a temperate seasonal climate. Its capital and largest city is Riga. Latvians, who are the titular nation and comprise 65.5% of the country's population, belong to the ethnolinguistic group of the Balts and speak Latvian. Russians are the most prominent minority in the country, at almost a quarter of the population; 37.7% of the population speak Russian as their native tongue.","currencyCode":"EUR"},{"name":"Morocco","officialName":"Kingdom of Morocco","nativeName":"المغرب","continent":"Africa","region":"Africa","subregion":"Northern Africa","capital":"Rabat","area":446550,"population":0,"languages":"Arabic, Berber","currencies":"Moroccan dirham","borders":"DZA, ESH, ESP","summary":"Morocco, officially the Kingdom of Morocco, is a country in the Maghreb region of North Africa. It has coastlines on the Mediterranean Sea to the north and the Atlantic Ocean to the west, and has land borders with Algeria to the east; the Spanish exclaves of Ceuta, Melilla and Peñón de Vélez de la Gomera along the north, which it claims together with several small Spanish-controlled islands; and the disputed territory of Western Sahara to the south, partly occupied by Morocco since 1975. Morocco also claims to share a border with Mauritania through the disputed territory of Western Sahara. It has a population of approximately 37 million. Its capital is Rabat, while its largest city is Casablanca.","currencyCode":"MAD"},{"name":"Monaco","officialName":"Principality of Monaco","nativeName":"Monaco","continent":"Europe","region":"Europe","subregion":"Western Europe","capital":"Monaco","area":2.02,"population":0,"languages":"French","currencies":"Euro","borders":"FRA","summary":"","currencyCode":"EUR"},{"name":"Moldova","officialName":"Republic of Moldova","nativeName":"Moldova","continent":"Europe","region":"Europe","subregion":"Eastern Europe","capital":"Chișinău","area":33846,"population":0,"languages":"Moldavian","currencies":"Moldovan leu","borders":"ROU, UKR","summary":"Moldova, officially the Republic of Moldova, is a landlocked country in Eastern Europe, with an area of 33,843 km2 (13,067 sq mi) and a population of 2.38 million. Moldova is bordered by Romania to the west and Ukraine to the north, east, and south. The unrecognised breakaway state of Transnistria lies across the Dniester river on the country's eastern border with Ukraine. Moldova is a parliamentary democratic republic with its capital in Chișinău, the country's largest city and main cultural and commercial centre.","currencyCode":"MDL"},{"name":"Madagascar","officialName":"Republic of Madagascar","nativeName":"Madagascar","continent":"Africa","region":"Africa","subregion":"Eastern Africa","capital":"Antananarivo","area":587041,"population":0,"languages":"French, Malagasy","currencies":"Malagasy ariary","borders":"","summary":"","currencyCode":"MGA"},{"name":"Maldives","officialName":"Republic of the Maldives","nativeName":"ދިވެހިރާއްޖޭގެ","continent":"Asia","region":"Asia","subregion":"Southern Asia","capital":"Malé","area":300,"population":0,"languages":"Maldivian","currencies":"Maldivian rufiyaa","borders":"","summary":"The Maldives, officially the Republic of Maldives, and historically known as the Maldive Islands, is an archipelagic country in South Asia, located in the Indian Ocean, near the southeastern boundary of the Arabian Sea. The Maldives is located southwest of India and Sri Lanka, about 750 kilometres from the Asian continent's mainland. The Maldives' chain of 26 atolls stretches across the equator from Ihavandhippolhu Atoll in the north to Addu Atoll in the south.","currencyCode":"MVR"},{"name":"Mexico","officialName":"United Mexican States","nativeName":"México","continent":"North America","region":"Americas","subregion":"North America","capital":"Mexico City","area":1964375,"population":0,"languages":"Spanish","currencies":"Mexican peso","borders":"BLZ, GTM, USA","summary":"Mexico, officially the United Mexican States, is a country in North America. It is the northernmost country in Latin America, bordering the United States of America to the north and Guatemala and Belize to the southeast, while having maritime boundaries with the Pacific Ocean to the west, the Caribbean Sea to the southeast, and the Gulf of Mexico to the east. Mexico covers 1,972,550 km2, and is the thirteenth-largest country in the world by land area. With a population exceeding 134 million as of 2026, Mexico is the tenth-most populous country in the world and is home to the largest number of native Spanish speakers. Mexico City is the capital and largest city in Mexico, which ranks among the most populous metropolitan areas in the world.","currencyCode":"MXN"},{"name":"Marshall Islands","officialName":"Republic of the Marshall Islands","nativeName":"Marshall Islands","continent":"Oceania","region":"Oceania","subregion":"Micronesia","capital":"Majuro","area":181,"population":0,"languages":"English, Marshallese","currencies":"United States dollar","borders":"","summary":"The Marshall Islands, officially the Republic of the Marshall Islands, is an archipelagic country in Oceania. The sovereign state lies west of the International Date Line and north of the equator in the Micronesia region of the Northwestern Pacific Ocean.","currencyCode":"USD"},{"name":"North Macedonia","officialName":"Republic of North Macedonia","nativeName":"Македонија","continent":"Europe","region":"Europe","subregion":"Southeast Europe","capital":"Skopje","area":25713,"population":0,"languages":"Macedonian","currencies":"denar","borders":"ALB, BGR, GRC, UNK, SRB","summary":"North Macedonia, officially the Republic of North Macedonia, is a landlocked country in Southeast Europe. It shares land borders with Greece to the south, Albania to the west, Bulgaria to the east, Kosovo to the northwest and Serbia to the north. It constitutes approximately the northern third of the larger geographical region of Macedonia. Skopje, the capital and largest city, is home to a quarter of the country's population of over 1.83 million. The majority of the residents are ethnic Macedonians, a South Slavic people. Albanians form a significant minority at around 25%, followed by Turks, Roma, Serbs, Bosniaks, Aromanians and a few other minorities.","currencyCode":"MKD"},{"name":"Mali","officialName":"Republic of Mali","nativeName":"Mali","continent":"Africa","region":"Africa","subregion":"Western Africa","capital":"Bamako","area":1240192,"population":0,"languages":"French","currencies":"West African CFA franc","borders":"DZA, BFA, GIN, CIV, MRT, NER, SEN","summary":"Mali, officially the Republic of Mali, is a landlocked country in West Africa. It is the eighth-largest country in Africa and the 23rd largest country in the world, with an area of 1,240,192 square kilometres (478,841 sq mi). It is bordered to the north by Algeria, to the east by Niger, to the northwest by Mauritania, to the south by Burkina Faso and Ivory Coast, and to the west by Guinea and Senegal. The population is about 25.20 million, 47.19% of which are estimated to be under age 15 in 2024. Its capital and largest city is Bamako. French was the official language until 2022, when it was replaced by 13 African languages, with Bambara being the first language of the majority of the population.","currencyCode":"XOF"},{"name":"Malta","officialName":"Republic of Malta","nativeName":"Malta","continent":"Europe","region":"Europe","subregion":"Southern Europe","capital":"Valletta","area":316,"population":0,"languages":"English, Maltese","currencies":"Euro","borders":"","summary":"Malta, officially the Republic of Malta, is an island country located in the central Mediterranean Sea. It consists of an archipelago which is 80 km (50 mi) south of Italy, 284 km (176 mi) east of Tunisia, and 333 km (207 mi) north of Libya. The two official languages are Maltese and English; Maltese is recognised as the national language. The country's capital is Valletta, which is the smallest capital city in the European Union by both area and population.","currencyCode":"EUR"},{"name":"Myanmar","officialName":"Republic of the Union of Myanmar","nativeName":"မြန်မာ","continent":"Asia","region":"Asia","subregion":"South-Eastern Asia","capital":"Naypyidaw","area":676578,"population":0,"languages":"Burmese","currencies":"Burmese kyat","borders":"BGD, CHN, IND, LAO, THA","summary":"Myanmar, officially the Republic of the Union of Myanmar and also referred to as Burma, is a country in northwest Southeast Asia. It is the largest country by area in Mainland Southeast Asia and has a population of about 55 million. It is bordered by India and Bangladesh to the northwest, China to the northeast, Laos and Thailand to the east and southeast, and the Andaman Sea and the Bay of Bengal to the south and southwest. The country's capital city is Naypyidaw, while its largest city is Yangon.","currencyCode":"MMK"},{"name":"Montenegro","officialName":"Montenegro","nativeName":"Црна Гора","continent":"Europe","region":"Europe","subregion":"Southeast Europe","capital":"Podgorica","area":13812,"population":0,"languages":"Montenegrin","currencies":"Euro","borders":"ALB, BIH, HRV, UNK, SRB","summary":"Montenegro is a country in Southeast Europe, on the Balkan Peninsula. Its 25 municipalities have a total population of 633,158 people in an area of 13,883 km2. It is bordered by Serbia to the northeast, Bosnia and Herzegovina to the northwest, Kosovo to the east, Albania to the southeast, and Croatia to the west, and has a coastline along the Adriatic Sea to the southwest. The capital and largest city is Podgorica, while Cetinje is the Old Royal Capital and cultural centre.","currencyCode":"EUR"},{"name":"Mongolia","officialName":"Mongolia","nativeName":"Монгол улс","continent":"Asia","region":"Asia","subregion":"Eastern Asia","capital":"Ulan Bator","area":1564110,"population":0,"languages":"Mongolian","currencies":"Mongolian tögrög","borders":"CHN, RUS","summary":"","currencyCode":"MNT"},{"name":"Mozambique","officialName":"Republic of Mozambique","nativeName":"Moçambique","continent":"Africa","region":"Africa","subregion":"Eastern Africa","capital":"Maputo","area":801590,"population":0,"languages":"Portuguese","currencies":"Mozambican metical","borders":"MWI, ZAF, SWZ, TZA, ZMB, ZWE","summary":"","currencyCode":"MZN"},{"name":"Mauritania","officialName":"Islamic Republic of Mauritania","nativeName":"موريتانيا","continent":"Africa","region":"Africa","subregion":"Western Africa","capital":"Nouakchott","area":1030700,"population":0,"languages":"Arabic","currencies":"Mauritanian ouguiya","borders":"DZA, MLI, SEN, ESH","summary":"Mauritania, officially the Islamic Republic of Mauritania, is a country in the Maghreb region of West Africa. It is bordered by the Atlantic Ocean to the west, Western Sahara to the north and northwest, Algeria to the northeast, Mali to the east and southeast, and Senegal to the southwest. By land area Mauritania is the 11th-largest country in Africa and the 28th-largest in the world; 90% of its territory is in the Sahara desert. Most of its population of 5.4 million live in the temperate south of the country; roughly a third of the population is concentrated in the capital and largest city, Nouakchott, on the Atlantic coast.","currencyCode":"MRU"},{"name":"Mauritius","officialName":"Republic of Mauritius","nativeName":"Mauritius","continent":"Africa","region":"Africa","subregion":"Eastern Africa","capital":"Port Louis","area":2040,"population":0,"languages":"English, French, Mauritian Creole","currencies":"Mauritian rupee","borders":"","summary":"Mauritius, officially the Republic of Mauritius, is an island country in the Indian Ocean, located about 1,100 nautical miles off the southeastern coast of Africa, east of Madagascar. It includes the main island, as well as Rodrigues, Agaléga, and St. Brandon. The islands of Mauritius and Rodrigues, along with nearby Réunion, are part of the Mascarene Islands. The main island of Mauritius, where the population is concentrated, hosts the capital and largest city, Port Louis. The country spans 2,040 square kilometres (790 sq mi) and has an exclusive economic zone covering approximately 580,000 square nautical miles.","currencyCode":"MUR"},{"name":"Malawi","officialName":"Republic of Malawi","nativeName":"Malawi","continent":"Africa","region":"Africa","subregion":"Eastern Africa","capital":"Lilongwe","area":118484,"population":0,"languages":"English, Chewa","currencies":"Malawian kwacha","borders":"MOZ, TZA, ZMB","summary":"","currencyCode":"MWK"},{"name":"Malaysia","officialName":"Malaysia","nativeName":"Malaysia","continent":"Asia","region":"Asia","subregion":"South-Eastern Asia","capital":"Kuala Lumpur","area":330803,"population":0,"languages":"English, Malay","currencies":"Malaysian ringgit","borders":"BRN, IDN, THA","summary":"Malaysia is a country in Southeast Asia. A federal constitutional monarchy, it consists of 13 states and three federal territories, separated by the South China Sea into two regions: Peninsular Malaysia on Mainland Southeast Asia and East Malaysia on the island of Borneo. Peninsular Malaysia shares land and maritime borders with Thailand, as well as maritime borders with Singapore, Vietnam, and Indonesia; East Malaysia shares land borders with Brunei and Indonesia, and maritime borders with the Philippines and Vietnam. Kuala Lumpur is the country's national capital, largest city, and the seat of the legislative branch of the federal government, while Putrajaya is the federal administrative capital, representing the seat of both the executive branch and the judicial branch of the federal government. With a population of over 34 million, it is the world's 43rd-most populous country.","currencyCode":"MYR"},{"name":"Namibia","officialName":"Republic of Namibia","nativeName":"Namibië","continent":"Africa","region":"Africa","subregion":"Southern Africa","capital":"Windhoek","area":825615,"population":0,"languages":"Afrikaans, German, English, Herero, Khoekhoe, Kwangali, Lozi, Ndonga, Tswana","currencies":"Namibian dollar, South African rand","borders":"AGO, BWA, ZAF, ZMB","summary":"Namibia, officially the Republic of Namibia, is a country in Southern Africa. It borders the Atlantic Ocean to the west, Zambia and Angola to the north, Botswana to the east, and South Africa to the south; in the northeast, approximating a quadripoint, Zimbabwe lies less than 200 metres (660 ft) away along the Zambezi river near Kazungula, Zambia. Namibia's capital and largest city is Windhoek.","currencyCode":"NAD"},{"name":"Niger","officialName":"Republic of Niger","nativeName":"Niger","continent":"Africa","region":"Africa","subregion":"Western Africa","capital":"Niamey","area":1267000,"population":0,"languages":"French","currencies":"West African CFA franc","borders":"DZA, BEN, BFA, TCD, LBY, MLI, NGA","summary":"","currencyCode":"XOF"},{"name":"Nigeria","officialName":"Federal Republic of Nigeria","nativeName":"Nigeria","continent":"Africa","region":"Africa","subregion":"Western Africa","capital":"Abuja","area":923768,"population":0,"languages":"English","currencies":"Nigerian naira","borders":"BEN, CMR, TCD, NER","summary":"Nigeria, officially the Federal Republic of Nigeria, is a country in West Africa between the Sahel to the north and the Gulf of Guinea in the Atlantic Ocean to the south. It covers an area of 923,769 square kilometres (356,669 mi2). With a population of more than 242 million, it is the most populous country in Africa, and the world's sixth-most populous country. Nigeria borders Niger in the north, Chad in the northeast, Cameroon in the east, and Benin in the west. Nigeria is a federal republic comprising 36 states and the Federal Capital Territory, where its capital, Abuja, is located. The largest city in Nigeria by population is Lagos, one of the largest metropolitan areas in the world and the second largest in Africa.","currencyCode":"NGN"},{"name":"Nicaragua","officialName":"Republic of Nicaragua","nativeName":"Nicaragua","continent":"North America","region":"Americas","subregion":"Central America","capital":"Managua","area":130373,"population":0,"languages":"Spanish","currencies":"Nicaraguan córdoba","borders":"CRI, HND","summary":"Nicaragua, officially the Republic of Nicaragua, is a country in Central America, comprising 130,370 square kilometers (50,340 sq mi). With a population of 7,097,329 as of 2026, it is the third-most populous country in Central America after Guatemala and Honduras, and the largest by area in all of Central America.","currencyCode":"NIO"},{"name":"Netherlands","officialName":"Kingdom of the Netherlands","nativeName":"Nederland","continent":"Europe","region":"Europe","subregion":"Western Europe","capital":"Amsterdam","area":41850,"population":0,"languages":"Dutch","currencies":"Euro","borders":"BEL, DEU","summary":"The Netherlands, also informally known as Holland, is a country in Northwestern Europe, with overseas territories in the Caribbean. It is the largest of the four constituent countries of the Kingdom of the Netherlands. The Netherlands consists of twelve provinces and three overseas special municipalities. European Netherlands has land borders with Germany to the east and with Belgium to the south, and a coastline to the north and west. It shares maritime borders with the United Kingdom, Germany, and Belgium in the North Sea. The official language is Dutch, with West Frisian as a secondary official language in the province of Friesland. Dutch, English, and Papiamento are official in the Caribbean territories. People from the Netherlands are referred to as Dutch.","currencyCode":"EUR"},{"name":"Norway","officialName":"Kingdom of Norway","nativeName":"Noreg","continent":"Europe","region":"Europe","subregion":"Northern Europe","capital":"Oslo","area":323802,"population":0,"languages":"Norwegian Nynorsk, Norwegian Bokmål, Sami","currencies":"Norwegian krone","borders":"FIN, SWE, RUS","summary":"","currencyCode":"NOK"},{"name":"Nepal","officialName":"Federal Democratic Republic of Nepal","nativeName":"नेपाल","continent":"Asia","region":"Asia","subregion":"Southern Asia","capital":"Kathmandu","area":147181,"population":0,"languages":"Nepali","currencies":"Nepalese rupee","borders":"CHN, IND","summary":"Nepal, officially the Federal Democratic Republic of Nepal, is a landlocked country in South Asia. It is mainly situated in the Himalayas, but also includes parts of the Indo-Gangetic Plain. It borders the Tibet Autonomous Region of China to the north, and India to the south, east, and west, while it is narrowly separated from Bangladesh by the Siliguri Corridor, and from Bhutan by the Indian state of Sikkim. Nepal has a diverse geography, including fertile plains, subalpine forested hills, and eight of the world's ten highest mountains, including Mount Everest, the highest point above mean sea level on Earth. Kathmandu is the nation's capital and its largest city. Nepal is a multi-ethnic, multi-lingual, multi-religious, and multi-cultural sovereign state, with Nepali as the official language.","currencyCode":"NPR"},{"name":"Nauru","officialName":"Republic of Nauru","nativeName":"Nauru","continent":"Oceania","region":"Oceania","subregion":"Micronesia","capital":"Yaren","area":21,"population":0,"languages":"English, Nauru","currencies":"Australian dollar","borders":"","summary":"","currencyCode":"AUD"},{"name":"New Zealand","officialName":"New Zealand","nativeName":"New Zealand","continent":"Oceania","region":"Oceania","subregion":"Australia and New Zealand","capital":"Wellington","area":270467,"population":0,"languages":"English, Māori, New Zealand Sign Language","currencies":"New Zealand dollar","borders":"","summary":"New Zealand is an island country in the southwestern Pacific Ocean. It comprises two main landmasses—the North Island and the South Island —and over 700 smaller islands. It is the sixth-largest island country by area and lies east of Australia across the Tasman Sea and south of the islands of New Caledonia, Fiji, and Tonga. The country's varied topography and sharp mountain peaks, including the Southern Alps, owe much to tectonic uplift and volcanic eruptions. New Zealand's capital city is Wellington, and its most populous city is Auckland.","currencyCode":"NZD"},{"name":"Oman","officialName":"Sultanate of Oman","nativeName":"عمان","continent":"Asia","region":"Asia","subregion":"Western Asia","capital":"Muscat","area":309500,"population":0,"languages":"Arabic","currencies":"Omani rial","borders":"SAU, ARE, YEM","summary":"Oman, officially the Sultanate of Oman, is a country in the southeastern Arabian Peninsula in West Asia. It shares land borders with Saudi Arabia, the United Arab Emirates, and Yemen, and maritime borders with Iran and Pakistan. Its coastline extends along the Arabian Sea to the southeast and the Gulf of Oman to the northeast. The exclaves of Madha and Musandam are surrounded by the United Arab Emirates on their land borders, while Musandam's coastal boundaries are formed by the Strait of Hormuz and the Gulf of Oman. With an area of 315,331 km2 and a population of approximately 5.46 million, Oman is the third-largest country on the Arabian Peninsula. Muscat is the capital and largest city, Islam is the state religion, and Arabic is the official language.","currencyCode":"OMR"},{"name":"Pakistan","officialName":"Islamic Republic of Pakistan","nativeName":"Pakistan","continent":"Asia","region":"Asia","subregion":"Southern Asia","capital":"Islamabad","area":881912,"population":0,"languages":"English, Urdu","currencies":"Pakistani rupee","borders":"AFG, CHN, IND, IRN","summary":"Pakistan, officially the Islamic Republic of Pakistan, is a country in South Asia. It is the fifth-most populous country, with a population of over 241.5 million, having the second-largest Muslim population in the world as of 2023. Islamabad is the nation's capital, while Karachi is its largest city and financial centre. Pakistan is the 33rd-largest country by area. Bounded by the Arabian Sea on the south, the Gulf of Oman on the southwest, and the Sir Creek on the southeast, it shares land borders with India to the east; Afghanistan to the west; Iran to the southwest; and China to the northeast. It shares a maritime border with Oman in the Gulf of Oman, and is separated from Tajikistan in the northwest by Afghanistan's narrow Wakhan Corridor.","currencyCode":"PKR"},{"name":"Panama","officialName":"Republic of Panama","nativeName":"Panamá","continent":"North America","region":"Americas","subregion":"Central America","capital":"Panama City","area":75417,"population":0,"languages":"Spanish","currencies":"Panamanian balboa, United States dollar","borders":"COL, CRI","summary":"Panama, officially the Republic of Panama, is a country located at the southern end of Central America in North America, bordering South America. It is bordered by Costa Rica to the west, Colombia to the southeast, the Caribbean Sea to the north, and the Pacific Ocean to the south. Its capital and largest city is Panama City, whose metropolitan area is home to nearly half of the country's over 4 million inhabitants.","currencyCode":"PAB"},{"name":"Peru","officialName":"Republic of Peru","nativeName":"Piruw","continent":"South America","region":"Americas","subregion":"South America","capital":"Lima","area":1285216,"population":0,"languages":"Aymara, Quechua, Spanish","currencies":"Peruvian sol","borders":"BOL, BRA, CHL, COL, ECU","summary":"Peru, officially the Republic of Peru, is a country in western South America. It is bordered to the north by Ecuador and Colombia, to the east by Brazil, to the southeast by Bolivia, to the south by Chile, and to the south and west by the Pacific Ocean. Peru is a megadiverse country, with habitats ranging from the arid plains of the Pacific coastal region in the west, to the peaks of the Andes mountains extending from the north to the southeast of the country, to the tropical Amazon basin rainforest in the east with the Amazon River. Peru has a population of over 32 million, and its capital and largest city is Lima. At 1,285,216 km2 (496,225 sq mi), Peru is the 19th largest country in the world, and the third largest in South America.","currencyCode":"PEN"},{"name":"Philippines","officialName":"Republic of the Philippines","nativeName":"Philippines","continent":"Asia","region":"Asia","subregion":"South-Eastern Asia","capital":"Manila","area":342353,"population":0,"languages":"English, Filipino","currencies":"Philippine peso","borders":"","summary":"The Philippines, officially the Republic of the Philippines, is an archipelagic country in Southeast Asia. Located in the western Pacific Ocean, it consists of about 7,641 islands, with a total area of about 300,000 square kilometers. The islands are broadly categorized in three main geographical divisions. From north to south, the divisions are: Luzon, Visayas, and Mindanao. With a population of over 114 million, it is the world's thirteenth-most-populous country.","currencyCode":"PHP"},{"name":"Palau","officialName":"Republic of Palau","nativeName":"Palau","continent":"Oceania","region":"Oceania","subregion":"Micronesia","capital":"Ngerulmud","area":459,"population":0,"languages":"English, Palauan","currencies":"United States dollar","borders":"","summary":"Palau, officially the Republic of Palau, is an island country located in the Micronesia subregion of Oceania in the western Pacific Ocean. The Republic of Palau consists of approximately 340 islands and is the western part of the Caroline Islands, while the eastern and central parts make up the Federated States of Micronesia.","currencyCode":"USD"},{"name":"Papua New Guinea","officialName":"Independent State of Papua New Guinea","nativeName":"Papua New Guinea","continent":"Oceania","region":"Oceania","subregion":"Melanesia","capital":"Port Moresby","area":462840,"population":0,"languages":"English, Hiri Motu, Tok Pisin","currencies":"Papua New Guinean kina","borders":"IDN","summary":"","currencyCode":"PGK"},{"name":"Poland","officialName":"Republic of Poland","nativeName":"Polska","continent":"Europe","region":"Europe","subregion":"Central Europe","capital":"Warsaw","area":312679,"population":0,"languages":"Polish","currencies":"Polish złoty","borders":"BLR, CZE, DEU, LTU, RUS, SVK, UKR","summary":"Poland, officially the Republic of Poland, is a country in Central Europe. It extends from the Baltic Sea in the north to the Sudetes and Carpathian Mountains in the south, and borders Lithuania and Russia to the northeast; Belarus and Ukraine to the east; Slovakia and the Czech Republic to the south; and Germany to the west. The territory has a varied landscape, diverse ecosystems, and a temperate climate. Poland is composed of sixteen voivodeships and is the fifth most populous member state of the European Union (EU), with over 38 million people, and the fifth largest EU country by land area, covering 312,696 km2 (120,733 sq mi). The capital and largest city is Warsaw; other major cities include Kraków, Wrocław, Łódź, Poznań, and Gdańsk.","currencyCode":"PLN"},{"name":"North Korea","officialName":"Democratic People's Republic of Korea","nativeName":"조선","continent":"Asia","region":"Asia","subregion":"Eastern Asia","capital":"Pyongyang","area":120538,"population":0,"languages":"Korean","currencies":"North Korean won","borders":"CHN, KOR, RUS","summary":"","currencyCode":"KPW"},{"name":"Portugal","officialName":"Portuguese Republic","nativeName":"Portugal","continent":"Europe","region":"Europe","subregion":"Southern Europe","capital":"Lisbon","area":92090,"population":0,"languages":"Portuguese","currencies":"Euro","borders":"ESP","summary":"Portugal, officially the Portuguese Republic, is a country in Southwestern Europe. Mainland Portugal is located on the southwestern portion of the Iberian Peninsula, and bordered by Spain to the north and east. Portugal also includes the archipelagos of Madeira and the Azores in the Atlantic Ocean. The country has a population of 11.4 million, and Lisbon, its capital, is the largest city. Portugal's internal waters and territorial sea together account for two-fifths of its territory, and its exclusive economic zone is one of Europe's largest. The country's terrain contains a diverse range of landscapes and regional climates.","currencyCode":"EUR"},{"name":"Paraguay","officialName":"Republic of Paraguay","nativeName":"Paraguái","continent":"South America","region":"Americas","subregion":"South America","capital":"Asunción","area":406752,"population":0,"languages":"Guaraní, Spanish","currencies":"Paraguayan guaraní","borders":"ARG, BOL, BRA","summary":"Paraguay, officially the Republic of Paraguay, is a landlocked country located in the central region of South America. It borders Bolivia to the northwest and north, Brazil to the northeast and east, and Argentina to the southeast, south, and west. Paraguay has access to the Atlantic Ocean via the Paraná–Paraguay Waterway, a system of navigable channels shared by five countries. The country is governed as a unitary presidential republic composed of a capital district and seventeen departments. Its capital and largest city is Asunción. It dates its independence from Spain to 1811.","currencyCode":"PYG"},{"name":"Qatar","officialName":"State of Qatar","nativeName":"قطر","continent":"Asia","region":"Asia","subregion":"Western Asia","capital":"Doha","area":11586,"population":0,"languages":"Arabic","currencies":"Qatari riyal","borders":"SAU","summary":"Qatar, officially the State of Qatar, is a country in West Asia. It occupies the Qatar Peninsula on the northeastern coast of the Arabian Peninsula in the Middle East; it shares its sole land border with Saudi Arabia to the south, with the rest of its territory surrounded by the Persian Gulf. The Gulf of Bahrain, an inlet of the Persian Gulf, separates Qatar from nearby Bahrain. The capital is Doha, home to over 80% of the country's inhabitants. Most of the land area is made up of flat, low-lying desert.","currencyCode":"QAR"},{"name":"Romania","officialName":"Romania","nativeName":"România","continent":"Europe","region":"Europe","subregion":"Southeast Europe","capital":"Bucharest","area":238391,"population":0,"languages":"Romanian","currencies":"Romanian leu","borders":"BGR, HUN, MDA, SRB, UKR","summary":"Romania is a country in Central and Southeastern Europe. It lies on the lower course of the Danube, north of the Balkan Peninsula, and on the northwestern shore of the Black Sea. It borders Ukraine to the north and east, Hungary to the west, Serbia to the southwest, Bulgaria to the south, Moldova to the east, and the Black Sea to the southeast. It is the twelfth-largest country in Europe by area, covering 238,397 km2 (92,046 mi2), and the sixth-most populous member state of the European Union, with 19 million inhabitants. The capital, largest city and economic centre is Bucharest. Other major cities include Cluj-Napoca, Iași, Constanța, Timișoara, Brașov and Craiova.","currencyCode":"RON"},{"name":"Russia","officialName":"Russian Federation","nativeName":"Россия","continent":"Europe","region":"Europe","subregion":"Eastern Europe","capital":"Moscow","area":17098242,"population":0,"languages":"Russian","currencies":"Russian ruble","borders":"AZE, BLR, CHN, EST, FIN, GEO, KAZ, PRK, LVA, LTU, MNG, NOR, POL, UKR","summary":"Russia, or the Russian Federation, is a country in Eastern Europe and North Asia. It is the largest country in the world, spanning eleven time zones and sharing land borders with fourteen countries. With a population of over 140 million, Russia is the most populous country in Europe and the ninth-most populous in the world. It is a highly urbanised country, with sixteen of its urban areas having more than 1 million inhabitants. Moscow, the most populous metropolitan area in Europe, is the capital and largest city of Russia, while Saint Petersburg is its second-largest city and a major cultural centre.","currencyCode":"RUB"},{"name":"Rwanda","officialName":"Republic of Rwanda","nativeName":"Rwanda","continent":"Africa","region":"Africa","subregion":"Eastern Africa","capital":"Kigali","area":26338,"population":0,"languages":"English, French, Kinyarwanda","currencies":"Rwandan franc","borders":"BDI, COD, TZA, UGA","summary":"","currencyCode":"RWF"},{"name":"Saudi Arabia","officialName":"Kingdom of Saudi Arabia","nativeName":"السعودية","continent":"Asia","region":"Asia","subregion":"Western Asia","capital":"Riyadh","area":2149690,"population":0,"languages":"Arabic","currencies":"Saudi riyal","borders":"IRQ, JOR, KWT, OMN, QAT, ARE, YEM","summary":"Saudi Arabia, officially the Kingdom of Saudi Arabia (KSA), is a country in West Asia that occupies the bulk of the Arabian Peninsula. Covering a land area of approximately 2,149,690 km2 (830,000 sq mi), it is the fifth-largest country in Asia and the twelfth-largest in the world. It is bordered by the Red Sea to the west, Jordan, Iraq, and Kuwait to the north, the Arabian Gulf, Bahrain, Qatar, and the United Arab Emirates to the east, Oman to the southeast, and Yemen to the south. The Gulf of Aqaba in the northwest separates it from Egypt and Israel. Riyadh is the capital and largest city, while other major centers include Jeddah and the two holiest cities in Islam, Mecca and Medina.","currencyCode":"SAR"},{"name":"Sudan","officialName":"Republic of the Sudan","nativeName":"السودان","continent":"Africa","region":"Africa","subregion":"Northern Africa","capital":"Khartoum","area":1886068,"population":0,"languages":"Arabic, English","currencies":"Sudanese pound","borders":"CAF, TCD, EGY, ERI, ETH, LBY, SSD","summary":"Sudan, officially the Republic of the Sudan, is a country in Northeast Africa. It borders the Central African Republic to the southwest, Chad to the west, Libya to the northwest, Egypt to the north, the Red Sea to the east, Eritrea and Ethiopia to the southeast, and South Sudan to the south. Sudan has a population of 51.8 million people as of 2025 and occupies 1,886,068 square kilometres, making it Africa's third-largest country by area. Sudan's capital and most populous city is Khartoum.","currencyCode":"SDG"},{"name":"Senegal","officialName":"Republic of Senegal","nativeName":"Sénégal","continent":"Africa","region":"Africa","subregion":"Western Africa","capital":"Dakar","area":196722,"population":0,"languages":"French","currencies":"West African CFA franc","borders":"GMB, GIN, GNB, MLI, MRT","summary":"Senegal, officially the Republic of Senegal, is the westernmost country of mainland West Africa, situated along the Atlantic Ocean coast. It borders Mauritania to the north, Mali to the east, Guinea to the southeast and Guinea-Bissau to the southwest. Senegal nearly surrounds the Gambia, a country occupying a narrow strip of land along the banks of the Gambia River, which separates Senegal's southern region of Casamance from the rest of the country. It also shares a maritime border with Cape Verde. The capital and largest city of Senegal is Dakar.","currencyCode":"XOF"},{"name":"Singapore","officialName":"Republic of Singapore","nativeName":"Singapore","continent":"Asia","region":"Asia","subregion":"South-Eastern Asia","capital":"Singapore","area":710,"population":0,"languages":"English, Malay, Tamil, Chinese","currencies":"Singapore dollar","borders":"","summary":"Singapore, officially the Republic of Singapore, is an island country in Southeast Asia. Its territory comprises a main island, over 60 satellite islands and islets, and one outlying islet. The country is about one degree of latitude north of the equator, off the southern tip of the Malay Peninsula, bordering the Strait of Malacca to the west, the Singapore Strait to the south along with the Riau Islands in Indonesia, the South China Sea to the east and the Straits of Johor along with the State of Johor in Malaysia to the north.","currencyCode":"SGD"},{"name":"Solomon Islands","officialName":"Solomon Islands","nativeName":"Solomon Islands","continent":"Oceania","region":"Oceania","subregion":"Melanesia","capital":"Honiara","area":28896,"population":0,"languages":"English","currencies":"Solomon Islands dollar","borders":"","summary":"Solomon Islands, also known simply as the Solomons, is an archipelagic country consisting of six major islands and over 1,000 smaller islands in Melanesia, Oceania, to the north-east of Australia. It is adjacent to Bougainville to the west, New Caledonia and Vanuatu to the south-east, Fiji, Tuvalu, and Wallis and Futuna to the east, and the Federated States of Micronesia and Nauru to the north. It has a total area of 28,896 square kilometres, and a population of 828,857 according to official estimates from 2025. Its capital and largest city, Honiara, is located on the largest island, Guadalcanal. The country takes its name from the wider area of the Solomon Islands archipelago, which is a collection of Melanesian islands that also includes the Autonomous Region of Bougainville, but excludes the Santa Cruz Islands.","currencyCode":"SBD"},{"name":"Sierra Leone","officialName":"Republic of Sierra Leone","nativeName":"Sierra Leone","continent":"Africa","region":"Africa","subregion":"Western Africa","capital":"Freetown","area":71740,"population":0,"languages":"English","currencies":"Sierra Leonean leone","borders":"GIN, LBR","summary":"","currencyCode":"SLE"},{"name":"El Salvador","officialName":"Republic of El Salvador","nativeName":"El Salvador","continent":"North America","region":"Americas","subregion":"Central America","capital":"San Salvador","area":21041,"population":0,"languages":"Spanish","currencies":"United States dollar","borders":"GTM, HND","summary":"","currencyCode":"USD"},{"name":"San Marino","officialName":"Most Serene Republic of San Marino","nativeName":"San Marino","continent":"Europe","region":"Europe","subregion":"Southern Europe","capital":"City of San Marino","area":61,"population":0,"languages":"Italian","currencies":"Euro","borders":"ITA","summary":"San Marino, officially the Republic of San Marino, is a landlocked country in Southern Europe, completely surrounded by Italy. Located on the northeastern slopes of the Apennine Mountains, it is the larger of two microstates within the Italian Peninsula, the other being Vatican City. San Marino is the fifth-smallest country in the world, with a land area of just over 61 square kilometres (24 sq mi) and a population of 34,042 as of 2025 which in 2026 dropped to 33,559. Its capital, the City of San Marino, sits atop Monte Titano, while its largest settlement is Dogana, in the municipality of Serravalle. San Marino claims to have been founded in AD 301 and to be the oldest extant sovereign state, and the oldest constitutional republic. It is named after Saint Marinus, a legendary stonemason from the Roman island of Rab, who is said to have fled persecution under Emperor Diocletian to have established a monastic community on Monte Titano, where he built a small chapel. The country has a rare constitutional structure: the Grand and General Council, a democratically elected legislature, selects two heads of state, the Captains Regent, every six months. They are chosen from opposing political parties, and serve concurrently with equal powers and preside over several institutions of state, including the Grand and General Council. Only the Federal Council of Switzerland follows this same structure, except with some modifications due to its immensely larger size.","currencyCode":"EUR"},{"name":"Somalia","officialName":"Federal Republic of Somalia","nativeName":"الصومال","continent":"Africa","region":"Africa","subregion":"Eastern Africa","capital":"Mogadishu","area":637657,"population":0,"languages":"Arabic, Somali","currencies":"Somali shilling","borders":"DJI, ETH, KEN","summary":"Somalia, officially the Federal Republic of Somalia, is the easternmost country in continental Africa. Stretching across the Horn of Africa, it borders Ethiopia to the west, Djibouti to the northwest, Kenya to the southwest, the Gulf of Aden to the north, and the Indian Ocean to the east. Somalia has the longest coastline on Africa's mainland. Somalia has an estimated population over 19 million, of which 2.7 million live in the capital and largest city, Mogadishu. As one of Africa's most ethnically homogeneous countries, around 85% of its residents are ethnic Somalis. The official and national language of the country is Somali, and Arabic is recognised as a second language. The overwhelming majority of the population are Sunni Muslims.","currencyCode":"SOS"},{"name":"Serbia","officialName":"Republic of Serbia","nativeName":"Србија","continent":"Europe","region":"Europe","subregion":"Southeast Europe","capital":"Belgrade","area":88361,"population":0,"languages":"Serbian","currencies":"Serbian dinar","borders":"BIH, BGR, HRV, HUN, UNK, MKD, MNE, ROU","summary":"Serbia, officially the Republic of Serbia, is a landlocked country in Southeastern and Central Europe. It is bordered by Hungary to the north, Romania to the northeast, Bulgaria to the southeast, North Macedonia to the south, Croatia to the northwest, Bosnia and Herzegovina to the west, Montenegro to the southwest, and it also claims a border with Albania through the disputed territory of Kosovo. \nSerbia has about 6.5 million inhabitants, with its capital, Belgrade, being its largest city.","currencyCode":"RSD"},{"name":"South Sudan","officialName":"Republic of South Sudan","nativeName":"South Sudan","continent":"Africa","region":"Africa","subregion":"Middle Africa","capital":"Juba","area":619745,"population":0,"languages":"English","currencies":"South Sudanese pound","borders":"CAF, COD, ETH, KEN, SDN, UGA","summary":"South Sudan, officially the Republic of South Sudan, is a landlocked country in East Africa. It is bordered by Sudan to the north, Ethiopia to the east, Kenya to the southeast, Uganda to the south, the Democratic Republic of the Congo to the southwest, and the Central African Republic to the west. South Sudan's diverse landscape includes vast plains and plateaus, dry and tropical savannahs, inland floodplains, and forested mountains. The Nile River system is the defining physical feature of the country, running south to north across its center, which is dominated by a large swamp known as the Sudd. South Sudan has an estimated population of just over 12.7 million in 2024. Juba is the capital and largest city.","currencyCode":"SSP"},{"name":"São Tomé and Príncipe","officialName":"Democratic Republic of São Tomé and Príncipe","nativeName":"São Tomé e Príncipe","continent":"Africa","region":"Africa","subregion":"Middle Africa","capital":"São Tomé","area":964,"population":0,"languages":"Portuguese","currencies":"São Tomé and Príncipe dobra","borders":"","summary":"São Tomé and Príncipe, officially the Democratic Republic of Sao Tome and Principe, is an island country in the Gulf of Guinea, off the western equatorial coast of Central Africa. It consists of two archipelagos around the two main islands of São Tomé and Príncipe, about 81 nautical miles apart and about 135 and 121 nautical miles off the northwestern coast of Gabon. With a population of 201,800, São Tomé and Príncipe is the second-smallest and second-least populous African sovereign state after Seychelles.","currencyCode":"STN"},{"name":"Suriname","officialName":"Republic of Suriname","nativeName":"Suriname","continent":"South America","region":"Americas","subregion":"South America","capital":"Paramaribo","area":163820,"population":0,"languages":"Dutch","currencies":"Surinamese dollar","borders":"BRA, GUF, GUY","summary":"","currencyCode":"SRD"},{"name":"Slovakia","officialName":"Slovak Republic","nativeName":"Slovensko","continent":"Europe","region":"Europe","subregion":"Central Europe","capital":"Bratislava","area":49037,"population":0,"languages":"Slovak","currencies":"Euro","borders":"AUT, CZE, HUN, POL, UKR","summary":"","currencyCode":"EUR"},{"name":"Slovenia","officialName":"Republic of Slovenia","nativeName":"Slovenija","continent":"Europe","region":"Europe","subregion":"Central Europe","capital":"Ljubljana","area":20273,"population":0,"languages":"Slovene","currencies":"Euro","borders":"AUT, HRV, ITA, HUN","summary":"Slovenia, officially the Republic of Slovenia, is a country in Central Europe. It borders Italy to its west, Austria to its north, Hungary to its northeast, and Croatia to its south and southeast; its southwestern boundary consists of a 46.6-kilometre (29.0 mi) coastline on the Adriatic Sea. The country is mostly mountainous and forested, covering 20,271 square kilometres (7,827 sq mi). Its population is approximately 2.1 million people. Slovene is the official language. Slovenia has a predominantly temperate continental climate, with the exception of the Slovene Littoral and the Julian Alps. Ljubljana, the capital and largest city, is geographically situated near the centre of the country. Other urban centers include Maribor, Ptuj, Kranj, Celje, Koper, Novo Mesto, Velenje, Nova Gorica, Sežana, Murska Sobota, and Jesenice.","currencyCode":"EUR"},{"name":"Sweden","officialName":"Kingdom of Sweden","nativeName":"Sverige","continent":"Europe","region":"Europe","subregion":"Northern Europe","capital":"Stockholm","area":450295,"population":0,"languages":"Swedish","currencies":"Swedish krona","borders":"FIN, NOR","summary":"","currencyCode":"SEK"},{"name":"Eswatini","officialName":"Kingdom of Eswatini","nativeName":"Eswatini","continent":"Africa","region":"Africa","subregion":"Southern Africa","capital":"Lobamba","area":17364,"population":0,"languages":"English, Swazi","currencies":"Swazi lilangeni, South African rand","borders":"MOZ, ZAF","summary":"Eswatini, formally the Kingdom of Eswatini, also known by its former official names Swaziland and the Kingdom of Swaziland, is a landlocked country in Southern Africa. It is bordered by South Africa on all sides except the east, where it shares a border with Mozambique. At no more than 200 km (120 mi) north to south and 130 km (81 mi) east to west, Eswatini is the second smallest country in continental Africa. However, its climate and topography are diverse, ranging from a cool and mountainous highveld to a hot and dry lowveld. The executive capital and largest city is Mbabane, and the legislative and second capital is Lobamba.","currencyCode":"SZL"},{"name":"Seychelles","officialName":"Republic of Seychelles","nativeName":"Sesel","continent":"Africa","region":"Africa","subregion":"Eastern Africa","capital":"Victoria","area":452,"population":0,"languages":"Seychellois Creole, English, French","currencies":"Seychellois rupee","borders":"","summary":"Seychelles, officially the Republic of Seychelles, is an archipelagic country consisting of 115 islands in the Indian Ocean. Its capital and largest city, Victoria, is 1,500 kilometres east of mainland Africa. Nearby island countries and territories include the Maldives, Comoros, Madagascar, Mauritius, and the French overseas departments of Mayotte and Réunion to the south; and the Chagos Archipelago to the east.\nSeychelles is the smallest country in Africa as well as the least populated sovereign African country, with an estimated population of 100,600 in 2022.","currencyCode":"SCR"},{"name":"Syria","officialName":"Syrian Arab Republic","nativeName":"سوريا","continent":"Asia","region":"Asia","subregion":"Western Asia","capital":"Damascus","area":185180,"population":0,"languages":"Arabic","currencies":"Syrian pound","borders":"IRQ, ISR, JOR, LBN, TUR","summary":"","currencyCode":"SYP"},{"name":"Chad","officialName":"Republic of Chad","nativeName":"تشاد","continent":"Africa","region":"Africa","subregion":"Middle Africa","capital":"N'Djamena","area":1284000,"population":0,"languages":"Arabic, French","currencies":"Central African CFA franc","borders":"CMR, CAF, LBY, NER, NGA, SDN","summary":"Chad, officially the Republic of Chad, is a landlocked country in Central Africa. It is bordered by Libya to the north, Sudan to the east, the Central African Republic to the south, Cameroon to the southwest, Nigeria to the southwest, and Niger to the west. Chad has a population of 20 million, of which 1.6 million live in the capital and largest city of N'Djamena. With a total area of around 1,300,000 km2 (500,000 sq mi), Chad is the fifth-largest country in Africa and the twentieth largest nation by area.","currencyCode":"XAF"},{"name":"Togo","officialName":"Togolese Republic","nativeName":"Togo","continent":"Africa","region":"Africa","subregion":"Western Africa","capital":"Lomé","area":56785,"population":0,"languages":"French","currencies":"West African CFA franc","borders":"BEN, BFA, GHA","summary":"Togo, officially the Togolese Republic, is a country located in West Africa. It is bordered by Ghana to the west, Benin to the east and Burkina Faso to the north. It is one of the least developed countries in the world. It extends north from the Gulf of Guinea to the Burkina Faso-Togo border. It is a small, tropical country, spanning 57,000 square kilometres with a population of approximately 8 million. It has a width of less than 115 km (71 mi) between Ghana and its eastern neighbour Benin.","currencyCode":"XOF"},{"name":"Thailand","officialName":"Kingdom of Thailand","nativeName":"ประเทศไทย","continent":"Asia","region":"Asia","subregion":"South-Eastern Asia","capital":"Bangkok","area":513120,"population":0,"languages":"Thai","currencies":"Thai baht","borders":"MMR, KHM, LAO, MYS","summary":"Thailand, officially the Kingdom of Thailand, and formerly known as Siam, is a country located in Mainland Southeast Asia. It shares land borders with Myanmar to the west and northwest, Laos to the east and northeast, Cambodia to the southeast, and Malaysia to the south. Its maritime boundaries include the Gulf of Thailand and the Andaman Sea, and it shares maritime borders with Vietnam, Indonesia, and India. Thailand has a population of nearly 66 million people and covers an area of approximately 513,115 km2. The capital and largest city is Bangkok.","currencyCode":"THB"},{"name":"Tajikistan","officialName":"Republic of Tajikistan","nativeName":"Таджикистан","continent":"Asia","region":"Asia","subregion":"Central Asia","capital":"Dushanbe","area":143100,"population":0,"languages":"Russian, Tajik","currencies":"Tajikistani somoni","borders":"AFG, CHN, KGZ, UZB","summary":"","currencyCode":"TJS"},{"name":"Turkmenistan","officialName":"Turkmenistan","nativeName":"Туркмения","continent":"Asia","region":"Asia","subregion":"Central Asia","capital":"Ashgabat","area":488100,"population":0,"languages":"Russian, Turkmen","currencies":"Turkmenistan manat","borders":"AFG, IRN, KAZ, UZB","summary":"Turkmenistan is a landlocked country in Central Asia, bordered by Kazakhstan and Uzbekistan to the north, Afghanistan to the southeast, Iran to the south and southwest, and the Caspian Sea to the west. It is one of six independent Turkic states. Ashgabat is the capital and largest city. With over 7 million people, Turkmenistan is the 35th most-populous country in Asia and has the lowest population of the Central Asian republics while being one of the most sparsely populated nations located on the Asian continent.","currencyCode":"TMT"},{"name":"Timor-Leste","officialName":"Democratic Republic of Timor-Leste","nativeName":"Timor-Leste","continent":"Asia","region":"Asia","subregion":"South-Eastern Asia","capital":"Dili","area":14874,"population":0,"languages":"Portuguese, Tetum","currencies":"United States dollar","borders":"IDN","summary":"Timor-Leste, also known as East Timor, officially the Democratic Republic of Timor-Leste, is a country in Southeast Asia. It comprises the eastern half of the island of Timor, the coastal exclave of Oecusse in the island's northwest, and the islands of Atauro and Jaco, for a total land area of 15,007 square kilometres (5,794 sq mi). Timor-Leste shares a land border with Indonesia to the west; Australia is the country's southern neighbour, across the Timor Sea. Dili, on the north coast of Timor, is its capital and largest city.","currencyCode":"USD"},{"name":"Tonga","officialName":"Kingdom of Tonga","nativeName":"Tonga","continent":"Oceania","region":"Oceania","subregion":"Polynesia","capital":"Nuku'alofa","area":747,"population":0,"languages":"English, Tongan","currencies":"Tongan paʻanga","borders":"","summary":"Tonga, officially known as the Kingdom of Tonga, is an island country in Polynesia, part of Oceania. The country has 171 islands, of which 45 are inhabited. Its total surface area is about 750 km2 (290 sq mi), scattered over 700,000 km2 (270,000 sq mi) in the southern Pacific Ocean. As of September 2026, Tonga has a population of 103,291, 70% of whom live on the main island, Tongatapu. The country stretches approximately 800 km north-south. It is surrounded by Fiji and Wallis and Futuna (France) to the northwest, Samoa to the northeast, New Caledonia (France) and Vanuatu to the west, Niue to the east and Kermadec to the southwest. Tonga is about 1,800 km from New Zealand's North Island.","currencyCode":"TOP"},{"name":"Trinidad and Tobago","officialName":"Republic of Trinidad and Tobago","nativeName":"Trinidad and Tobago","continent":"North America","region":"Americas","subregion":"Caribbean","capital":"Port of Spain","area":5130,"population":0,"languages":"English","currencies":"Trinidad and Tobago dollar","borders":"","summary":"Trinidad and Tobago, officially the Republic of Trinidad and Tobago, is the southernmost archipelagic country in the Caribbean, comprising the main islands of Trinidad and Tobago, along with several smaller islets. The capital city is Port of Spain, while its largest and most populous municipality is Chaguanas. Trinidad and Tobago comprises the southernmost islands of the Caribbean eastern islands chain, and it is close to the continent of South America, being north to northeast of Venezuela and northwest of Guyana.","currencyCode":"TTD"},{"name":"Tunisia","officialName":"Tunisian Republic","nativeName":"تونس","continent":"Africa","region":"Africa","subregion":"Northern Africa","capital":"Tunis","area":163610,"population":0,"languages":"Arabic","currencies":"Tunisian dinar","borders":"DZA, LBY","summary":"","currencyCode":"TND"},{"name":"Türkiye","officialName":"Republic of Türkiye","nativeName":"Türkiye","continent":"Asia","region":"Asia","subregion":"Western Asia","capital":"Ankara","area":783562,"population":0,"languages":"Turkish","currencies":"Turkish lira","borders":"ARM, AZE, BGR, GEO, GRC, IRN, IRQ, SYR","summary":"","currencyCode":"TRY"},{"name":"Tuvalu","officialName":"Tuvalu","nativeName":"Tuvalu","continent":"Oceania","region":"Oceania","subregion":"Polynesia","capital":"Funafuti","area":26,"population":0,"languages":"English, Tuvaluan","currencies":"Australian dollar, Tuvaluan dollar","borders":"","summary":"","currencyCode":"AUD"},{"name":"Tanzania","officialName":"United Republic of Tanzania","nativeName":"Tanzania","continent":"Africa","region":"Africa","subregion":"Eastern Africa","capital":"Dodoma","area":945087,"population":0,"languages":"English, Swahili","currencies":"Tanzanian shilling","borders":"BDI, COD, KEN, MWI, MOZ, RWA, UGA, ZMB","summary":"Tanzania, officially the United Republic of Tanzania, is a country in East Africa within the African Great Lakes region. It is bordered by Uganda to the northwest, Kenya to the northeast, the Indian Ocean to the east, Mozambique and Malawi to the south, Zambia to the southwest, and Rwanda, Burundi, and the Democratic Republic of the Congo to the west. According to a 2024 estimate, Tanzania has a population of around 67.5 million, making it the most populous African country located entirely south of the equator.","currencyCode":"TZS"},{"name":"Uganda","officialName":"Republic of Uganda","nativeName":"Uganda","continent":"Africa","region":"Africa","subregion":"Eastern Africa","capital":"Kampala","area":241550,"population":0,"languages":"English, Swahili","currencies":"Ugandan shilling","borders":"COD, KEN, RWA, SSD, TZA","summary":"Uganda, officially the Republic of Uganda, is a landlocked country in East Africa. It is bordered to the east by Kenya, to the north by South Sudan, to the west by the Democratic Republic of the Congo, to the south-west by Rwanda, and to the south by Tanzania. The southern part includes a substantial portion of Lake Victoria, shared with Kenya and Tanzania. Uganda is in the African Great Lakes region, lies within the Nile basin, and has a varied equatorial climate. As of 2024, it had a population of 45.9 million, of whom 1.8 million live in the capital and largest city, Kampala.","currencyCode":"UGX"},{"name":"Ukraine","officialName":"Ukraine","nativeName":"Україна","continent":"Europe","region":"Europe","subregion":"Eastern Europe","capital":"Kyiv","area":603500,"population":0,"languages":"Ukrainian","currencies":"Ukrainian hryvnia","borders":"BLR, HUN, MDA, POL, ROU, RUS, SVK","summary":"Ukraine is a country in Eastern Europe. It is the second-largest country in Europe after Russia, which borders it to the east and northeast. Ukraine also borders Belarus to the north; Poland and Slovakia to the west; Hungary, Romania and Moldova to the southwest; and the Black Sea and the Sea of Azov to the south and southeast. Kyiv is Ukraine's capital and largest city, followed by Kharkiv, Odesa, and Dnipro. The official language of the country is Ukrainian. Ukraine covers an area of 603,628 km2 (233,062 sq mi) with an estimated total population of 32.3 million in 2026.","currencyCode":"UAH"},{"name":"Uruguay","officialName":"Oriental Republic of Uruguay","nativeName":"Uruguay","continent":"South America","region":"Americas","subregion":"South America","capital":"Montevideo","area":181034,"population":0,"languages":"Spanish","currencies":"Uruguayan peso","borders":"ARG, BRA","summary":"Uruguay, officially the Oriental Republic of Uruguay, is a country in southeastern South America. It shares borders with Argentina to its west and southwest and Brazil to its north and northeast, while bordering the Río de la Plata to the south and the Atlantic Ocean to the southeast. It is part of the Southern Cone region of South America. Uruguay covers an area of approximately 176,215 square kilometers (68,037 sq mi). It has a population of almost 3.5 million people, of whom nearly 2 million live in the metropolitan area of its capital and largest city, Montevideo.","currencyCode":"UYU"},{"name":"United States","officialName":"United States of America","nativeName":"United States","continent":"North America","region":"Americas","subregion":"North America","capital":"Washington D.C.","area":9372610,"population":0,"languages":"English","currencies":"United States dollar","borders":"CAN, MEX","summary":"The United States of America (USA), also known as the United States (U.S.) or America, is a country primarily located in North America. It is a federal republic consisting of 50 states and a federal capital district, Washington, D.C. The 48 contiguous states border Canada to the north and Mexico to the south, with the semi-exclave of Alaska in the northwest and the archipelago of Hawaii in the Pacific Ocean. The United States also asserts sovereignty over five major island territories and various uninhabited islands in Oceania and the Caribbean. It is a megadiverse country, with the world's fourth-largest total area and third-largest population, exceeding 341 million.","currencyCode":"USD"},{"name":"Uzbekistan","officialName":"Republic of Uzbekistan","nativeName":"Узбекистан","continent":"Asia","region":"Asia","subregion":"Central Asia","capital":"Tashkent","area":447400,"population":0,"languages":"Russian, Uzbek","currencies":"Uzbekistani soʻm","borders":"AFG, KAZ, KGZ, TJK, TKM","summary":"Uzbekistan, officially the Republic of Uzbekistan, is a sovereign, doubly landlocked country located in Central Asia. It is bordered by Kazakhstan to the north, Kyrgyzstan to the northeast, Tajikistan to the southeast, Afghanistan to the south, and Turkmenistan to the south-west. It is one of only two doubly landlocked countries in the world, the other being Liechtenstein. The country has a population of more than 39 million, making it the most populous country in Central Asia. Uzbekistan is a member of the Organisation of Turkic States. Uzbek, spoken by the Uzbek people who form more than 89% of the population, is the official language of the country. Russian and Tajik are significant minority languages, with Russian serving as a lingua franca. Tajik is primarily spoken by Tajiks living in the southern parts of the country, such as Samarkand and Bukhara.","currencyCode":"UZS"},{"name":"Vatican City","officialName":"Vatican City State","nativeName":"Vaticano","continent":"Europe","region":"Europe","subregion":"Southern Europe","capital":"Vatican City","area":0.44,"population":0,"languages":"Italian, Latin","currencies":"Euro","borders":"ITA","summary":"Vatican City, officially the Vatican City State, often shortened as the Vatican, is a landlocked sovereign city-state in Southern Europe. Ruled by the pope, it is an enclave within the city of Rome, Italy, and serves as the administrative centre of the Catholic Church. Vatican City is governed by the See of Rome, commonly known as the Holy See, itself a sovereign entity under international law, which maintains its temporal power, governance, diplomacy, and spiritual independence. Vatican is also used as a metonym for the Holy See, which is the central governing body of the Catholic Church and Vatican City, comprising the pope and the Roman Curia. The independent state of Vatican City came into existence in 1929 via the Lateran Treaty between the Holy See and the Kingdom of Italy, which spoke of it as a creation, not as a vestige of the much larger Papal States (756–1870), which had previously encompassed much of Central Italy.","currencyCode":"EUR"},{"name":"Saint Vincent and the Grenadines","officialName":"Saint Vincent and the Grenadines","nativeName":"Saint Vincent and the Grenadines","continent":"North America","region":"Americas","subregion":"Caribbean","capital":"Kingstown","area":389,"population":0,"languages":"English","currencies":"Eastern Caribbean dollar","borders":"","summary":"Saint Vincent and the Grenadines, sometimes known simply as Saint Vincent, is an archipelagic country in the eastern Caribbean. It is located in the southeast Windward Islands of the Lesser Antilles, which lie in the West Indies, at the southern end of the eastern border between the Caribbean Sea and the Atlantic Ocean. To the north lies Saint Lucia, to the east is Barbados and Grenada lies to the south.","currencyCode":"XCD"},{"name":"Venezuela","officialName":"Bolivarian Republic of Venezuela","nativeName":"Venezuela","continent":"South America","region":"Americas","subregion":"South America","capital":"Caracas","area":916445,"population":0,"languages":"Spanish","currencies":"Venezuelan bolívar soberano","borders":"BRA, COL, GUY","summary":"Venezuela, officially the Bolivarian Republic of Venezuela, is a country on the northern coast of South America, consisting of a continental landmass and various islands and islets in the Caribbean Sea. It comprises an area of 912,050 km2 (352,140 sq mi), with a population estimated at 31.8 million in 2025. The capital and largest urban agglomeration is Caracas. The continental territory is bordered on the north by the Caribbean Sea and the Atlantic Ocean, on the west by Colombia, on the south by Brazil, on the east by Guyana, and on the northeast by Trinidad and Tobago. Venezuela consists of 23 states, the Capital District, and the Federal Dependencies covering Venezuela's offshore islands. Venezuela is among the most urbanized countries in Latin America, with an estimated urbanization rate of 88.4% in 2022. The vast majority of Venezuelans live in urban areas in the north, including in the capital.","currencyCode":"VES"},{"name":"Vietnam","officialName":"Socialist Republic of Vietnam","nativeName":"Việt Nam","continent":"Asia","region":"Asia","subregion":"South-Eastern Asia","capital":"Hanoi","area":331212,"population":0,"languages":"Vietnamese","currencies":"Vietnamese đồng","borders":"KHM, CHN, LAO","summary":"Vietnam, officially the Socialist Republic of Viet Nam (SRV), is a country at the eastern edge of Mainland Southeast Asia. With an area of about 331,000 square kilometres and a population of over 102 million, it is the world's 16th-most populous country. One of two communist states in Southeast Asia, Vietnam is bordered by China to the north, and Laos and Cambodia to the west; it lies along the Gulf of Thailand to the southwest and the South China Sea to the east, where it has shared and disputed maritime borders with other countries. Its capital is Hanoi, while its largest city is Ho Chi Minh City.","currencyCode":"VND"},{"name":"Vanuatu","officialName":"Republic of Vanuatu","nativeName":"Vanuatu","continent":"Oceania","region":"Oceania","subregion":"Melanesia","capital":"Port Vila","area":12189,"population":0,"languages":"Bislama, English, French","currencies":"Vanuatu vatu","borders":"","summary":"Vanuatu, officially the Republic of Vanuatu, is an archipelagic country in Melanesia located in the South Pacific Ocean. The archipelago, which is of volcanic origin, is 1,750 km (1,090 mi) east of northern Australia, 540 km (340 mi) northeast of New Caledonia, east of New Guinea, southeast of Solomon Islands, and west of Fiji.","currencyCode":"VUV"},{"name":"Samoa","officialName":"Independent State of Samoa","nativeName":"Samoa","continent":"Oceania","region":"Oceania","subregion":"Polynesia","capital":"Apia","area":2842,"population":0,"languages":"English, Samoan","currencies":"Samoan tālā","borders":"","summary":"Samoa, officially the Independent State of Samoa, is an island country in Polynesia, a part of Oceania, which is in the South Pacific Ocean. It consists of two main islands, two smaller, inhabited islands, and several smaller, uninhabited islands, including the Aleipata Islands. Samoa is located 64 km west of American Samoa, 889 km northeast of Tonga, 1,152 km northeast of Fiji, 483 km east of Wallis and Futuna, 1,151 km southeast of Tuvalu, 519 km south of Tokelau, 4,190 km southwest of Hawaii, and 610 km northwest of Niue. The capital and largest city is Apia.","currencyCode":"WST"},{"name":"Yemen","officialName":"Republic of Yemen","nativeName":"اليمن","continent":"Asia","region":"Asia","subregion":"Western Asia","capital":"Sana'a","area":527968,"population":0,"languages":"Arabic","currencies":"Yemeni rial","borders":"OMN, SAU","summary":"","currencyCode":"YER"},{"name":"South Africa","officialName":"Republic of South Africa","nativeName":"South Africa","continent":"Africa","region":"Africa","subregion":"Southern Africa","capital":"Pretoria, Bloemfontein, Cape Town","area":1221037,"population":0,"languages":"Afrikaans, English, Southern Ndebele, Northern Sotho, Southern Sotho, Swazi, Tswana, Tsonga, Venda, Xhosa, Zulu","currencies":"South African rand","borders":"BWA, LSO, MOZ, NAM, SWZ, ZWE","summary":"South Africa, officially the Republic of South Africa (RSA), is the southernmost country in Africa. The country consists of nine provinces, and is bounded to the south by 2,798 kilometres of coastline that stretches along the South Atlantic and Indian Ocean; to the north by the neighbouring countries of Namibia, Botswana, and Zimbabwe; and to the east and northeast by Mozambique and Eswatini. South Africa also encloses Lesotho. Covering an area of 1,221,037 square kilometres, the country has a population of over 63 million people, making it the sixth-most populated country in Africa, and 24th-most in the world. Pretoria is the administrative capital, while Cape Town, as the seat of Parliament, is the legislative capital, and Bloemfontein is regarded as the judicial capital. The largest and most populous city is Johannesburg, followed by Cape Town and Durban.","currencyCode":"ZAR"},{"name":"Zambia","officialName":"Republic of Zambia","nativeName":"Zambia","continent":"Africa","region":"Africa","subregion":"Eastern Africa","capital":"Lusaka","area":752612,"population":0,"languages":"English","currencies":"Zambian kwacha","borders":"AGO, BWA, COD, MWI, MOZ, NAM, TZA, ZWE","summary":"Zambia, officially the Republic of Zambia, is a landlocked country in Southern Africa. It is bordered to the north by the Democratic Republic of the Congo, Tanzania to the northeast, Malawi to the east, Mozambique to the southeast, Botswana and Zimbabwe to the south, Namibia to the southwest, and Angola to the west. The capital city of Zambia is Lusaka, located in the south-central part of Zambia. The population is concentrated mainly around Lusaka in the south and the Copperbelt Province to the north, the core economic hubs of Zambia.","currencyCode":"ZMW"},{"name":"Zimbabwe","officialName":"Republic of Zimbabwe","nativeName":"Zimbabwe","continent":"Africa","region":"Africa","subregion":"Eastern Africa","capital":"Harare","area":390757,"population":0,"languages":"Chibarwe, English, Kalanga, Khoisan, Ndau, Northern Ndebele, Chewa, Shona, Sotho, Tonga, Tswana, Tsonga, Venda, Xhosa, Zimbabwean Sign Language","currencies":"Botswana pula, Chinese yuan, Euro, British pound, Indian rupee, Japanese yen, United States dollar, South African rand, Zimbabwean bonds","borders":"BWA, MOZ, ZAF, ZMB","summary":"Zimbabwe, officially the Republic of Zimbabwe, is a landlocked country in Southeast Africa, between the Zambezi and Limpopo River, bordered by South Africa to the south, Botswana to the southwest, Zambia to the north, and Mozambique to the east. The capital and largest city is Harare, and the second largest is Bulawayo.","currencyCode":"BWP"}];
